.back-to-top {
  position: fixed;
  bottom: max(18px, env(safe-area-inset-bottom));
  right: max(14px, env(safe-area-inset-right));
  z-index: 1000;
  display: none;
  width: 58px;
  height: 58px;
  padding: 0;
  place-items: center;
  border: 2px solid #e2e2e2;
  border-radius: 8px;
  background: #ffffff;
  color: #707070;
  box-shadow: none;
  cursor: pointer;
  transition: none;
}

.catalog-jump-nav {
  position: fixed;
  right: max(14px, env(safe-area-inset-right));
  bottom: calc(max(18px, env(safe-area-inset-bottom)) + 68px);
  z-index: 1000;
  display: none;
  max-width: min(200px, calc(100vw - 28px));
  max-height: calc(100vh - 110px);
  padding: 3px;
  overflow-y: auto;
  justify-items: end;
  gap: 6px;
  scrollbar-width: thin;
}

.catalog-jump-nav.is-visible {
  display: grid;
}

.catalog-jump-btn {
  width: max-content;
  max-width: 194px;
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 9px 6px 7px;
  border: 1px solid #d8d8d8;
  border-radius: 7px;
  background: #ffffff;
  color: #475569;
  box-shadow: 0 2px 7px rgba(15, 23, 42, 0.12);
  cursor: pointer;
}

.catalog-jump-icon {
  flex: 0 0 21px;
  width: 21px;
  height: 21px;
  display: grid;
  place-items: center;
  border: 1px solid #c7d2fe;
  border-radius: 5px;
  background: #eef2ff;
  color: #4f46e5;
  font-size: 12px;
  font-weight: 900;
}

.catalog-jump-label {
  min-width: 0;
  overflow: hidden;
  color: inherit;
  font-size: 11px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.catalog-jump-btn:hover,
.catalog-jump-btn.is-active {
  border-color: #818cf8;
  background: #eef2ff;
  color: #3730a3;
}

.catalog-jump-btn:focus-visible {
  outline: 3px solid #93c5fd;
  outline-offset: 2px;
}

.prob-chip.catalog-jump-target {
  animation: catalog-jump-highlight 1.6s ease-out;
}

@keyframes catalog-jump-highlight {
  0%, 38% {
    border-color: #f59e0b;
    background: rgba(245, 158, 11, 0.2);
    box-shadow: 0 0 0 4px rgba(245, 158, 11, 0.24);
  }
  100% {
    border-color: #6366f1;
    background: rgba(99, 102, 241, 0.14);
    box-shadow: 0 0 0 1px rgba(99, 102, 241, 0.3);
  }
}

.back-to-top.is-visible {
  display: grid;
}

.back-to-top svg {
  width: 31px;
  height: 31px;
  stroke-width: 2.4;
}

.back-to-top:hover {
  border-color: #d8d8d8;
  background: #fafafa;
  color: #5f5f5f;
  transform: none;
}

.back-to-top:focus-visible {
  outline: 3px solid #93c5fd;
  outline-offset: 3px;
}

[data-theme="light"] .back-to-top {
  border-color: #e2e2e2;
  background: #ffffff;
  color: #707070;
  box-shadow: none;
}

[data-theme="light"] .back-to-top:hover {
  border-color: #d8d8d8;
  background: #fafafa;
  color: #5f5f5f;
}

[data-theme="light"] .catalog-jump-btn {
  border-color: #d8d8d8;
  background: #ffffff;
  color: #475569;
}

[data-theme="light"] .catalog-jump-btn:hover,
[data-theme="light"] .catalog-jump-btn.is-active {
  border-color: #818cf8;
  background: #eef2ff;
  color: #3730a3;
}

@media (max-width: 480px) {
  .back-to-top {
    bottom: max(14px, env(safe-area-inset-bottom));
    right: max(10px, env(safe-area-inset-right));
    width: 50px;
    height: 50px;
  }

  .back-to-top svg {
    width: 28px;
    height: 28px;
  }

  .catalog-jump-nav {
    right: max(10px, env(safe-area-inset-right));
    bottom: calc(max(14px, env(safe-area-inset-bottom)) + 58px);
    max-width: min(176px, calc(100vw - 20px));
    max-height: calc(100vh - 86px);
    gap: 5px;
  }

  .catalog-jump-btn {
    max-width: 170px;
    min-height: 33px;
    padding: 5px 8px 5px 6px;
  }

  .catalog-jump-label { font-size: 10px; }
}

@media (prefers-reduced-motion: reduce) {
  .prob-chip.catalog-jump-target { animation: none; outline: 3px solid #f59e0b; outline-offset: 2px; }
}

* {
  box-sizing: border-box;
}

/* ---- LeetCode 1044: Longest Duplicate Substring ---- */
.ld1044-viz {
  display: grid;
  gap: 14px;
  padding: 18px;
  color: #e5e7eb;
  background: radial-gradient(circle at top right, rgba(14, 165, 233, 0.09), transparent 38%), #0b1220;
  border: 1px solid #263449;
