}

.problem-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.problem-tags {
  display: inline-flex;
  align-items: center;
}

.problem-tags-hover {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
}

.problem-tags-trigger {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 1px solid rgba(56, 189, 248, 0.48);
  border-radius: 999px;
  color: #bae6fd;
  background: rgba(14, 165, 233, 0.14);
  cursor: help;
}

.problem-tags-trigger::before {
  content: "#";
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
}

.problem-tags-tooltip {
  position: absolute;
  z-index: 80;
  top: calc(100% + 7px);
  left: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  width: max-content;
  max-width: min(320px, calc(100vw - 40px));
  padding: 8px;
  border: 1px solid #475569;
  border-radius: 9px;
  color: #e2e8f0;
  background: #0f172a;
  box-shadow: 0 10px 28px rgba(2, 6, 23, 0.34);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(-3px);
  transition: opacity 0.14s ease, transform 0.14s ease, visibility 0.14s ease;
}

.problem-tags-hover:hover .problem-tags-tooltip,
.problem-tags-hover:focus-visible .problem-tags-tooltip,
.prob-chip:focus-visible .problem-tags-tooltip {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.problem-tags-hover:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
  border-radius: 999px;
}

.problem-tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 22px;
  padding: 2px 8px;
  border: 1px solid rgba(56, 189, 248, 0.48);
  border-radius: 999px;
  color: #bae6fd;
  background: rgba(14, 165, 233, 0.14);
  font-size: 9px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: 0.025em;
  white-space: nowrap;
}

.prob-meta .problem-tags-trigger {
  width: 19px;
  height: 19px;
}

.prob-meta .problem-tags-trigger::before {
  font-size: 10px;
}

.search-result-chip > .problem-tags-hover {
  align-self: center;
}

