/* ---- LeetCode 327: Count of Range Sum ---- */
.rs327-viz {
  min-height: 400px;
  padding: 18px;
  display: grid;
  gap: 13px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 12px;
  background:
    radial-gradient(circle at top right, rgba(34, 211, 238, 0.1), transparent 38%),
