/* ---- 491: Non-decreasing Subsequences ---- */
.nds-viz {
  display: grid;
  gap: 12px;
  width: 100%;
  min-width: 0;
}

.nds-phases {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-bottom: 1px solid rgba(148, 163, 184, 0.22);
}

.nds-phases span {
  min-width: 0;
  min-height: 38px;
  padding: 6px 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  color: #64748b;
  text-align: center;
}

.nds-phases span.is-active {
  border-bottom: 3px solid #f59e0b;
  color: #e2e8f0;
}

.nds-phases span.is-done {
  color: #6ee7b7;
}

.nds-phases b {
  min-width: 0;
  font-size: 10px;
  overflow-wrap: anywhere;
}

.nds-frame-bar {
  display: grid;
  grid-template-columns: 1.5fr repeat(2, minmax(0, 0.75fr));
  gap: 6px;
}

.nds-frame-bar > span {
  min-width: 0;
  min-height: 50px;
  padding: 6px 8px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 3px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.3);
  text-align: center;
}

.nds-frame-bar small {
  color: #94a3b8;
  font-size: 8px;
  font-weight: 800;
}

.nds-frame-bar strong {
  max-width: 100%;
  color: #f8fafc;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.nds-array-section,
.nds-current-section,
.nds-used-section,
.nds-checks-section,
.nds-stack-section,
.nds-results-section {
  min-width: 0;
}

.nds-array-section > header,
.nds-current-section > header,
.nds-used-section > header,
.nds-checks-section > header,
.nds-stack-section > header,
.nds-results-section > header {
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 7px;
  color: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 9px;
}

.nds-array-section > header strong,
.nds-current-section > header strong,
.nds-used-section > header strong,
.nds-checks-section > header strong,
.nds-stack-section > header strong,
.nds-results-section > header strong {
  color: #cbd5e1;
  font-size: 10px;
}

.nds-array-section > header span,
.nds-current-section > header span,
.nds-used-section > header span,
.nds-checks-section > header span,
.nds-stack-section > header span,
.nds-results-section > header span {
  min-width: 0;
  text-align: right;
  overflow-wrap: anywhere;
}

.nds-array {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 18px 0;
}

.nds-number {
  position: relative;
  width: 64px;
  min-height: 68px;
  padding: 9px 5px 7px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 3px;
  border: 1px solid rgba(148, 163, 184, 0.3);
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.38);
  transition: border-color 0.15s ease, background-color 0.15s ease, opacity 0.15s ease;
}

.nds-number > small {
  color: #64748b;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 9px;
}

.nds-number > strong {
  color: #f8fafc;
  font-size: 20px;
  line-height: 1;
}

.nds-number.is-before-start {
  opacity: 0.28;
}

.nds-number.is-chosen {
  border-color: #10b981;
  background: rgba(16, 185, 129, 0.16);
}

.nds-number.is-candidate {
  border-color: #22d3ee;
  background: rgba(34, 211, 238, 0.14);
  box-shadow: 0 0 0 3px rgba(34, 211, 238, 0.12);
