  left: 50%;
  padding: 2px 5px;
  border-radius: 3px;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 8px;
  font-style: normal;
  font-weight: 800;
  line-height: 1.2;
  transform: translateX(-50%);
  white-space: nowrap;
