}

.nds-stack > span.is-active {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.1);
}

.nds-stack > span small {
  color: #94a3b8;
  font-size: 8px;
}

.nds-stack > span strong {
  color: #e2e8f0;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 9px;
}

.nds-stack > b {
  color: #64748b;
  font-size: 10px;
}

.nds-results-section > small {
  display: block;
  margin-top: 5px;
  color: #64748b;
  font-size: 8px;
}

.nds-results > span {
