.ride-sharing-gate-source.is-driver { border-color: #0891b2; color: #67e8f9; }
.ride-sharing-gate-source.is-rider { border-color: #8b5cf6; color: #c4b5fd; }
.ride-sharing-gate > i { color: #64748b; font-style: normal; text-align: center; }

.ride-sharing-gate > div {
