}
.ride-sharing-gate > div small { color: #94a3b8; font-size: 8px; font-weight: 500; }
.ride-sharing-gate > div strong {
  color: #f8fafc;
  font: 500 17px/1.1 ui-monospace, SFMono-Regular, Menlo, monospace;
}
.ride-sharing-gate > div span { color: #64748b; font-size: 8px; }
.ride-sharing-gate.is-matched > div { border-left-color: #10b981; background: rgba(16, 185, 129, 0.1); }
.ride-sharing-gate.is-matched > div small,
.ride-sharing-gate.is-matched > div strong { color: #6ee7b7; }
