.ride-sharing-gate.is-no-match > div small,
.ride-sharing-gate.is-no-match > div strong { color: #fda4af; }
.ride-sharing-gate.is-cleaning > div { border-left-color: #f59e0b; background: rgba(245, 158, 11, 0.08); }
.ride-sharing-gate.is-cleaning > div small { color: #fbbf24; }

.ride-sharing-index-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  min-width: 0;
}

