.tree-annotation.recover-second { fill: #fb7185; }

.recover-traversal-row {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  color: #94a3b8;
