.bmax-rule {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 11px 13px;
  border-left: 4px solid #22c55e;
  background: rgba(34, 197, 94, 0.1);
}

.bmax-rule strong {
  flex: 0 0 auto;
  color: #bbf7d0;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
}

.bmax-rule span { max-width: 620px; color: #dcfce7; font-size: 10px; line-height: 1.45; text-align: right; }

.bmax-input > header,
.bmax-stack > header,
.bmax-new > header,
.bmax-all > header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.bmax-input > header strong,
.bmax-stack > header strong,
.bmax-new > header strong,
.bmax-all > header strong { color: #f8fafc; font-size: 10px; }
.bmax-input > header span,
.bmax-stack > header span,
.bmax-new > header span,
.bmax-all > header span { color: #94a3b8; font-size: 9px; text-align: right; }

.bmax-input > div {
  display: flex;
  gap: 7px;
  overflow-x: auto;
  padding: 2px 2px 7px;
}

.bmax-number {
  flex: 0 0 78px;
  min-height: 78px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
  padding: 7px;
  border: 1px solid #475569;
  border-radius: 7px;
  background: rgba(148, 163, 184, 0.05);
}

.bmax-number small { color: #94a3b8; font-size: 8px; }
.bmax-number strong { color: #f8fafc; font-size: 20px; line-height: 1; }
.bmax-number span { min-height: 12px; color: #94a3b8; font-size: 7px; font-weight: 900; }
.bmax-number.alive { border-color: #14b8a6; }
.bmax-number.left-boundary { border-color: #f59e0b; background: rgba(245, 158, 11, 0.14); }
.bmax-number.left-boundary span { color: #fcd34d; }
.bmax-number.current { border-color: #a78bfa; background: rgba(139, 92, 246, 0.2); box-shadow: inset 0 0 0 1px #8b5cf6; }
.bmax-number.current span { color: #ddd6fe; }
.bmax-number.popped { border-color: #fb7185; background: rgba(244, 63, 94, 0.14); opacity: 0.82; }
.bmax-number.popped span { color: #fda4af; }

.bmax-work {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(260px, 0.9fr) minmax(320px, 1.1fr);
  gap: 0;
  border-top: 1px solid #475569;
  border-bottom: 1px solid #475569;
}

.bmax-stack,
.bmax-new { min-width: 0; padding: 12px; }
.bmax-stack { border-right: 1px solid #475569; }
.bmax-stack > div:first-of-type {
  min-height: 88px;
  display: flex;
  align-items: center;
  gap: 7px;
  overflow-x: auto;
  padding-bottom: 6px;
}

.bmax-stack-group {
  flex: 0 0 116px;
  padding: 8px 9px;
  border: 1px solid #14b8a6;
  border-radius: 7px;
  background: rgba(20, 184, 166, 0.09);
}

.bmax-stack-group.top { border-color: #a78bfa; background: rgba(139, 92, 246, 0.15); }
.bmax-stack-group small { display: block; color: #5eead4; font-size: 7px; font-weight: 900; }
.bmax-stack-group.top small { color: #c4b5fd; }
.bmax-stack-group strong { display: block; margin: 3px 0; color: #f8fafc; font-size: 12px; }
.bmax-stack-group span { display: block; color: #ccfbf1; font-size: 9px; }
.bmax-stack-group em { display: block; margin-top: 3px; color: #cbd5e1; font-size: 8px; font-style: normal; }
.bmax-stack-arrow { flex: 0 0 auto; color: #5eead4; font-size: 12px; }
.bmax-empty { color: #94a3b8; font-size: 10px; font-style: normal; }

.bmax-pop-note {
  display: grid;
  grid-template-columns: auto auto 1fr;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  padding: 7px 9px;
  border-left: 3px solid #fb7185;
  background: rgba(244, 63, 94, 0.09);
}

.bmax-pop-note small { color: #fda4af; font-size: 8px; font-weight: 900; }
.bmax-pop-note strong { color: #ffe4e6; font-size: 10px; }
.bmax-pop-note span { color: #fecdd3; font-size: 9px; }

.bmax-ranges {
  min-width: 0;
  display: flex;
  gap: 7px;
  overflow-x: auto;
  padding: 2px 2px 7px;
}

.bmax-range {
  flex: 0 0 auto;
  min-width: 84px;
  padding: 7px 9px;
  border: 1px solid #475569;
  border-radius: 7px;
  background: rgba(148, 163, 184, 0.05);
}

.bmax-range small { display: block; color: #94a3b8; font-size: 8px; }
.bmax-range strong { display: block; margin-top: 3px; color: #e2e8f0; font-size: 9px; white-space: nowrap; }
.bmax-range.fresh { border-color: #22c55e; background: rgba(34, 197, 94, 0.12); }
.bmax-range.fresh small { color: #86efac; }
.bmax-range.fresh strong { color: #dcfce7; }

.bmax-equation {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-top: 8px;
  padding: 9px 11px;
  border-left: 4px solid #8b5cf6;
  background: rgba(139, 92, 246, 0.11);
}

.bmax-equation strong { color: #ddd6fe; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 15px; }
.bmax-equation span { color: #c4b5fd; font-size: 9px; text-align: right; }
.bmax-all { min-width: 0; }

.bmax-action {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 10px 12px;
  border-left: 4px solid #f59e0b;
  background: rgba(245, 158, 11, 0.09);
}

.bmax-action strong { flex: 0 0 34%; color: #fde68a; font-size: 10px; }
.bmax-action span { color: #fef3c7; font-size: 10px; line-height: 1.45; }

[data-theme="light"] .bmax-viz { color: #0f172a; }
[data-theme="light"] .bmax-phases,
[data-theme="light"] .bmax-phases span,
[data-theme="light"] .bmax-number,
[data-theme="light"] .bmax-work,
[data-theme="light"] .bmax-stack,
[data-theme="light"] .bmax-range { border-color: #cbd5e1; }
[data-theme="light"] .bmax-phases span { color: #64748b; }
[data-theme="light"] .bmax-phases span.active { background: #e0e7ff; color: #3730a3; }
[data-theme="light"] .bmax-rule { border-left-color: #15803d; background: #f0fdf4; }
[data-theme="light"] .bmax-rule strong { color: #166534; }
[data-theme="light"] .bmax-rule span { color: #14532d; }
[data-theme="light"] .bmax-input > header strong,
[data-theme="light"] .bmax-stack > header strong,
[data-theme="light"] .bmax-new > header strong,
[data-theme="light"] .bmax-all > header strong,
[data-theme="light"] .bmax-number strong,
[data-theme="light"] .bmax-stack-group strong { color: #0f172a; }
[data-theme="light"] .bmax-input > header span,
[data-theme="light"] .bmax-stack > header span,
[data-theme="light"] .bmax-new > header span,
[data-theme="light"] .bmax-all > header span,
[data-theme="light"] .bmax-number small,
[data-theme="light"] .bmax-number span,
[data-theme="light"] .bmax-empty { color: #64748b; }
[data-theme="light"] .bmax-number { background: #ffffff; }
[data-theme="light"] .bmax-number.alive { border-color: #0f766e; }
[data-theme="light"] .bmax-number.left-boundary { border-color: #d97706; background: #fffbeb; }
[data-theme="light"] .bmax-number.left-boundary span { color: #92400e; }
[data-theme="light"] .bmax-number.current { border-color: #7c3aed; background: #f3e8ff; box-shadow: inset 0 0 0 1px #7c3aed; }
[data-theme="light"] .bmax-number.current span { color: #5b21b6; }
[data-theme="light"] .bmax-number.popped { border-color: #e11d48; background: #fff1f2; }
[data-theme="light"] .bmax-number.popped span { color: #9f1239; }
[data-theme="light"] .bmax-stack-group { border-color: #0f766e; background: #f0fdfa; }
[data-theme="light"] .bmax-stack-group.top { border-color: #7c3aed; background: #f3e8ff; }
[data-theme="light"] .bmax-stack-group small,
[data-theme="light"] .bmax-stack-group span { color: #115e59; }
[data-theme="light"] .bmax-stack-group.top small { color: #6d28d9; }
[data-theme="light"] .bmax-stack-group em { color: #475569; }
[data-theme="light"] .bmax-pop-note { border-left-color: #be123c; background: #fff1f2; }
[data-theme="light"] .bmax-pop-note small,
[data-theme="light"] .bmax-pop-note strong,
[data-theme="light"] .bmax-pop-note span { color: #881337; }
[data-theme="light"] .bmax-range { background: #ffffff; }
[data-theme="light"] .bmax-range small { color: #64748b; }
[data-theme="light"] .bmax-range strong { color: #1e293b; }
[data-theme="light"] .bmax-range.fresh { border-color: #16a34a; background: #f0fdf4; }
[data-theme="light"] .bmax-range.fresh small,
[data-theme="light"] .bmax-range.fresh strong { color: #166534; }
[data-theme="light"] .bmax-equation { border-left-color: #7c3aed; background: #f5f3ff; }
[data-theme="light"] .bmax-equation strong { color: #5b21b6; }
[data-theme="light"] .bmax-equation span { color: #6d28d9; }
[data-theme="light"] .bmax-action { border-left-color: #d97706; background: #fffbeb; }
[data-theme="light"] .bmax-action strong { color: #92400e; }
[data-theme="light"] .bmax-action span { color: #78350f; }

@media (max-width: 760px) {
  .bmax-phases { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bmax-phases span { border-bottom: 1px solid #475569; }
  .bmax-phases span:nth-child(even) { border-right: 0; }
  .bmax-phases span:last-child { grid-column: 1 / -1; border-bottom: 0; }
  .bmax-rule,
  .bmax-action,
  .bmax-equation { align-items: flex-start; flex-direction: column; gap: 5px; }
  .bmax-rule strong { max-width: 100%; overflow-wrap: anywhere; }
  .bmax-rule span,
  .bmax-equation span { text-align: left; }
  .bmax-work { grid-template-columns: minmax(0, 1fr); }
  .bmax-stack { border-right: 0; border-bottom: 1px solid #475569; }
  .bmax-action strong { flex-basis: auto; }
  [data-theme="light"] .bmax-phases span,
  [data-theme="light"] .bmax-stack { border-color: #cbd5e1; }
}

/* ---- 3359: sorted submatrices by row width + column stack ---- */
.sortmat-viz {
  width: 100%;
  min-width: 0;
  max-width: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 13px;
  color: #e2e8f0;
  text-align: left;
}

.sortmat-phases {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  border: 1px solid #475569;
  border-radius: 7px;
  overflow: hidden;
}

.sortmat-phases span {
  min-width: 0;
  padding: 9px 5px;
  border-right: 1px solid #475569;
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  text-align: center;
}

.sortmat-phases span:last-child { border-right: 0; }
.sortmat-phases span.active { background: #0f766e; color: #f0fdfa; }

.sortmat-rule {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 12px;
  border-left: 4px solid #14b8a6;
  background: rgba(20, 184, 166, 0.1);
}

.sortmat-rule strong { color: #99f6e4; font-size: 10px; }
.sortmat-rule span { max-width: 640px; color: #ccfbf1; font-size: 10px; line-height: 1.45; text-align: right; }

.sortmat-main {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(330px, 1.25fr) minmax(260px, 0.75fr);
  gap: 12px;
}

.sortmat-matrix,
.sortmat-state,
.sortmat-stack,
.sortmat-candidates,
.sortmat-rectangles { min-width: 0; }

.sortmat-matrix > header,
.sortmat-state > header,
.sortmat-stack > header,
.sortmat-candidates > header,
.sortmat-rectangles > header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.sortmat-matrix > header strong,
.sortmat-state > header strong,
.sortmat-stack > header strong,
.sortmat-candidates > header strong,
.sortmat-rectangles > header strong { color: #f8fafc; font-size: 10px; }
.sortmat-matrix > header span,
.sortmat-state > header span,
.sortmat-stack > header span,
.sortmat-candidates > header span,
.sortmat-rectangles > header span { color: #94a3b8; font-size: 9px; text-align: right; }

.sortmat-matrix > div {
  display: grid;
  grid-template-columns: repeat(var(--sortmat-cols), minmax(70px, 1fr));
  gap: 6px;
  overflow-x: auto;
  padding: 2px 2px 7px;
}

.sortmat-cell {
  min-height: 76px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
  padding: 6px;
  border: 1px solid #475569;
  border-radius: 7px;
  background: rgba(148, 163, 184, 0.05);
}

.sortmat-cell small { color: #94a3b8; font-size: 7px; }
.sortmat-cell strong { color: #f8fafc; font-size: 18px; line-height: 1; }
.sortmat-cell span { color: #94a3b8; font-size: 8px; }
.sortmat-cell em { min-height: 11px; color: #86efac; font-size: 8px; font-style: normal; font-weight: 800; }
.sortmat-cell.ready { border-color: #475569; }
.sortmat-cell.active-column { border-color: #14b8a6; }
.sortmat-cell.row-segment { background: rgba(245, 158, 11, 0.14); border-color: #f59e0b; }
.sortmat-cell.current { background: rgba(139, 92, 246, 0.2); border-color: #a78bfa; box-shadow: inset 0 0 0 1px #8b5cf6; }
.sortmat-cell.blocked { background: rgba(244, 63, 94, 0.13); border-color: #fb7185; }
.sortmat-cell.blocked span { color: #fda4af; font-weight: 800; }

.sortmat-state {
  display: grid;
  align-content: start;
  padding-left: 12px;
  border-left: 1px solid #475569;
}

.sortmat-equation {
  min-height: 112px;
  display: grid;
  align-content: center;
  gap: 8px;
  padding: 11px 12px;
  border-left: 4px solid #8b5cf6;
  background: rgba(139, 92, 246, 0.11);
}

.sortmat-equation > strong { color: #ddd6fe; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; }
.sortmat-equation > span { color: #c4b5fd; font-size: 9px; }
.sortmat-equation > div { min-width: 0; }
.sortmat-equation > div + div { padding-top: 8px; border-top: 1px solid rgba(167, 139, 250, 0.3); }
.sortmat-equation small { display: block; color: #a78bfa; font-size: 7px; font-weight: 900; }
.sortmat-equation div strong { display: block; margin: 3px 0; color: #f5f3ff; font-size: 14px; }
.sortmat-equation div span { color: #c4b5fd; font-size: 8px; }

.sortmat-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 10px;
  color: #94a3b8;
  font-size: 8px;
}

.sortmat-legend span { display: inline-flex; align-items: center; gap: 4px; }
.sortmat-legend i { width: 9px; height: 9px; border: 1px solid #64748b; border-radius: 2px; }
.sortmat-legend i.segment { background: rgba(245, 158, 11, 0.35); border-color: #f59e0b; }
.sortmat-legend i.column { border-color: #14b8a6; }
.sortmat-legend i.blocked { background: rgba(244, 63, 94, 0.25); border-color: #fb7185; }

.sortmat-stack,
.sortmat-candidates,
.sortmat-rectangles {
  padding-top: 11px;
  border-top: 1px solid #475569;
}

.sortmat-stack > div:first-of-type,
.sortmat-candidates > div,
.sortmat-rectangles > div {
  min-height: 70px;
  display: flex;
  align-items: center;
  gap: 7px;
  overflow-x: auto;
  padding: 2px 2px 7px;
}

.sortmat-stack-item {
  flex: 0 0 112px;
  padding: 8px 9px;
  border: 1px solid #14b8a6;
  border-radius: 7px;
  background: rgba(20, 184, 166, 0.09);
}

.sortmat-stack-item.top { border-color: #a78bfa; background: rgba(139, 92, 246, 0.14); }
.sortmat-stack-item.sentinel { border-style: dashed; border-color: #64748b; background: rgba(100, 116, 139, 0.08); }
.sortmat-stack-item small { display: block; color: #5eead4; font-size: 7px; font-weight: 900; }
.sortmat-stack-item.sentinel small { color: #94a3b8; }
.sortmat-stack-item strong { display: block; margin: 3px 0; color: #f8fafc; font-size: 11px; }
.sortmat-stack-item span,
.sortmat-stack-item em { display: block; color: #cbd5e1; font-size: 8px; font-style: normal; }
.sortmat-arrow { flex: 0 0 auto; color: #5eead4; font-size: 12px; }
.sortmat-empty { color: #94a3b8; font-size: 10px; font-style: normal; }

.sortmat-popped {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  margin-top: 5px;
  padding: 7px 9px;
  border-left: 3px solid #fb7185;
  background: rgba(244, 63, 94, 0.09);
}

.sortmat-popped small { color: #fda4af; font-size: 8px; font-weight: 900; }
.sortmat-popped strong { color: #ffe4e6; font-size: 10px; }
.sortmat-popped span { color: #fecdd3; font-size: 9px; }

.sortmat-candidate {
  flex: 0 0 150px;
  padding: 8px 9px;
  border: 1px solid #f59e0b;
  border-radius: 7px;
  background: rgba(245, 158, 11, 0.1);
}

.sortmat-candidate small { display: block; color: #fcd34d; font-size: 8px; }
.sortmat-candidate strong { display: block; margin: 4px 0; color: #fef3c7; font-size: 11px; }
.sortmat-candidate span { color: #fde68a; font-size: 8px; }

.sortmat-rectangle {
  flex: 0 0 108px;
  padding: 7px 9px;
  border: 1px solid #22c55e;
  border-radius: 7px;
  background: rgba(34, 197, 94, 0.1);
}

.sortmat-rectangle small { display: block; color: #86efac; font-size: 8px; }
.sortmat-rectangle strong { display: block; margin-top: 3px; color: #dcfce7; font-size: 9px; }

.sortmat-action {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 10px 12px;
  border-left: 4px solid #38bdf8;
  background: rgba(56, 189, 248, 0.09);
