[data-theme="light"] .sortmat-stack-item.sentinel { border-color: #64748b; background: #f8fafc; }
[data-theme="light"] .sortmat-stack-item small,
[data-theme="light"] .sortmat-stack-item span,
[data-theme="light"] .sortmat-stack-item em { color: #475569; }
[data-theme="light"] .sortmat-candidate { border-color: #d97706; background: #fffbeb; }
[data-theme="light"] .sortmat-candidate small,
[data-theme="light"] .sortmat-candidate strong,
[data-theme="light"] .sortmat-candidate span { color: #78350f; }
[data-theme="light"] .sortmat-rectangle { border-color: #16a34a; background: #f0fdf4; }
[data-theme="light"] .sortmat-rectangle small,
[data-theme="light"] .sortmat-rectangle strong { color: #166534; }
[data-theme="light"] .sortmat-popped { border-left-color: #be123c; background: #fff1f2; }
[data-theme="light"] .sortmat-popped small,
[data-theme="light"] .sortmat-popped strong,
[data-theme="light"] .sortmat-popped span { color: #881337; }
[data-theme="light"] .sortmat-action { border-left-color: #0284c7; background: #f0f9ff; }
[data-theme="light"] .sortmat-action strong { color: #075985; }
[data-theme="light"] .sortmat-action span { color: #0c4a6e; }

@media (max-width: 760px) {
  .sortmat-phases { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .sortmat-phases span { border-bottom: 1px solid #475569; }
  .sortmat-phases span:nth-child(even) { border-right: 0; }
  .sortmat-phases span:last-child { grid-column: 1 / -1; border-bottom: 0; }
  .sortmat-rule,
  .sortmat-action { align-items: flex-start; flex-direction: column; gap: 5px; }
  .sortmat-rule span { text-align: left; }
  .sortmat-main { grid-template-columns: minmax(0, 1fr); }
  .sortmat-state { padding: 11px 0 0; border-left: 0; border-top: 1px solid #475569; }
  .sortmat-action strong { flex-basis: auto; }
  [data-theme="light"] .sortmat-phases span,
  [data-theme="light"] .sortmat-state { border-color: #cbd5e1; }
}

/* ---- Sentence pair visualization ---- */
.sentence-viz {
  min-height: 260px;
  padding: 18px;
  display: grid;
  gap: 18px;
  align-content: center;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 14px;
}

.sentence-title,
.sentence-pairs-label {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.sentence-columns {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 10px;
}

.sentence-column {
  min-width: 0;
  display: grid;
  grid-template-rows: minmax(42px, auto) 26px minmax(42px, auto) 16px;
  align-items: center;
  text-align: center;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 8px;
  background: rgba(148, 163, 184, 0.06);
  overflow: hidden;
}

.sentence-column.current {
  border-color: rgba(251, 191, 36, 0.8);
  box-shadow: 0 0 0 2px rgba(251, 191, 36, 0.14);
}

.sentence-word {
  min-width: 0;
  padding: 9px 7px;
  color: #e2e8f0;
  font-size: 15px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.sentence-relation {
  align-self: stretch;
  display: flex;
  align-items: center;
  justify-content: center;
  border-top: 1px solid rgba(148, 163, 184, 0.16);
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
  color: #94a3b8;
  font-size: 12px;
  font-weight: 800;
}

.sentence-column.identical .sentence-relation,
.sentence-column.similar .sentence-relation {
  background: rgba(16, 185, 129, 0.14);
  color: #5eead4;
}

.sentence-column.different .sentence-relation {
  background: rgba(239, 68, 68, 0.14);
  color: #fca5a5;
}

.sentence-column > small {
  color: #64748b;
  font-size: 10px;
}

.sentence-status {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 10px;
}

.sentence-status div {
  min-width: 0;
  padding: 9px 11px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
}

.sentence-status span {
  display: block;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.sentence-status strong {
  display: block;
  margin-top: 3px;
  color: #f8fafc;
  font-size: 15px;
  overflow-wrap: anywhere;
}

.sentence-pairs {
  margin-top: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.sentence-pair {
  padding: 5px 8px;
  border: 1px solid rgba(99, 102, 241, 0.32);
  border-radius: 6px;
  background: rgba(99, 102, 241, 0.12);
  color: #c7d2fe;
  font-size: 11px;
  font-weight: 700;
}

.sentence-pair.empty {
  color: #94a3b8;
  border-color: rgba(148, 163, 184, 0.24);
  background: rgba(148, 163, 184, 0.06);
}

/* ---- Synonymous Sentences (#1258) ---- */
.synonym-sentence-viz {
  display: grid;
  gap: 15px;
  min-width: 0;
  color: #e2e8f0;
  letter-spacing: 0;
}

.synonym-phases {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.synonym-phase {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 8px 9px;
  border-bottom: 2px solid rgba(148, 163, 184, 0.22);
  color: #64748b;
}

.synonym-phase span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 22px;
  width: 22px;
  height: 22px;
  border: 1px solid rgba(148, 163, 184, 0.32);
  border-radius: 50%;
  font-size: 10px;
  font-weight: 800;
}

.synonym-phase strong {
  min-width: 0;
  font-size: 11px;
  overflow-wrap: anywhere;
}

.synonym-phase.active {
  border-bottom-color: #38bdf8;
  color: #e0f2fe;
}

.synonym-phase.active span {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.14);
  color: #7dd3fc;
}

.synonym-phase.done {
  border-bottom-color: #10b981;
  color: #a7f3d0;
}

.synonym-phase.done span {
  border-color: #10b981;
  background: rgba(16, 185, 129, 0.13);
  color: #6ee7b7;
}

.synonym-action {
  padding: 10px 12px;
  border-left: 4px solid #38bdf8;
  background: rgba(56, 189, 248, 0.08);
  color: #bae6fd;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 13px;
  font-weight: 700;
  text-align: center;
  overflow-wrap: anywhere;
}

.synonym-pair-flow {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(176px, 1fr));
  gap: 7px;
}

.synonym-pair-step {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto minmax(0, 1fr);
  gap: 7px;
  align-items: center;
  min-width: 0;
  padding: 8px 9px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.34);
  color: #94a3b8;
  font-size: 11px;
  text-align: center;
}

.synonym-pair-step small {
  color: #64748b;
  font-size: 9px;
}

.synonym-pair-step span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.synonym-pair-step b { color: #64748b; }

.synonym-pair-step.current {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.1);
  color: #fde68a;
}

.synonym-pair-step.current b { color: #fbbf24; }

.synonym-pair-step.done {
  border-color: rgba(16, 185, 129, 0.38);
  background: rgba(16, 185, 129, 0.08);
  color: #a7f3d0;
}

.synonym-pair-step.done b { color: #34d399; }

.synonym-groups-section,
.synonym-dfs-section,
.synonym-decision-section,
.synonym-sentence-section,
.synonym-results-section {
  min-width: 0;
  padding-top: 11px;
  border-top: 1px solid rgba(148, 163, 184, 0.18);
}

.synonym-section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
  color: #94a3b8;
  font-size: 10px;
}

.synonym-section-heading strong {
  color: #cbd5e1;
  font-size: 11px;
}

.synonym-section-heading span { text-align: right; }

.synonym-dfs-section {
  display: grid;
  gap: 9px;
}

.synonym-dfs-status {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(150px, 0.75fr);
  gap: 8px;
}

.synonym-dfs-stack-block,
.synonym-dfs-event,
.synonym-dfs-working,
.synonym-dfs-choices {
  min-width: 0;
  padding: 8px 9px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.28);
}

.synonym-dfs-stack-block > small,
.synonym-dfs-event > small,
.synonym-dfs-working > small,
.synonym-dfs-choices > small {
  display: block;
  margin-bottom: 6px;
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
}

.synonym-dfs-stack {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}

.synonym-dfs-stack span {
  padding: 4px 6px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 5px;
  color: #cbd5e1;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 11px;
}

.synonym-dfs-stack span.active {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.12);
  color: #fde68a;
}

.synonym-dfs-stack span.empty { color: #64748b; }
.synonym-dfs-stack b { color: #64748b; font-size: 9px; }

.synonym-dfs-event strong {
  display: block;
  color: #bae6fd;
  font-size: 12px;
}

.synonym-dfs-working > div,
.synonym-dfs-choices > div {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.synonym-dfs-word {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 6px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 5px;
  color: #64748b;
  font-size: 11px;
}

.synonym-dfs-word small { color: inherit; font-size: 10px; }

.synonym-dfs-word.processed {
  border-color: rgba(56, 189, 248, 0.42);
  background: rgba(56, 189, 248, 0.08);
  color: #bae6fd;
}

.synonym-dfs-word.active {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.13);
  color: #fde68a;
}

.synonym-dfs-word.changed::after {
  content: "↺";
  color: #34d399;
  font-size: 9px;
}

.synonym-dfs-choice {
  padding: 4px 7px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 5px;
  color: #94a3b8;
  font-size: 11px;
}

.synonym-dfs-choice.current {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.12);
  color: #fde68a;
}

.synonym-dfs-choice.explored {
  border-color: rgba(16, 185, 129, 0.48);
  background: rgba(16, 185, 129, 0.08);
  color: #a7f3d0;
}

.synonym-dfs-no-choices {
  color: #64748b;
  font-size: 11px;
}

.synonym-decision-section {
  min-width: 0;
}

.synonym-decision-legend {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 7px;
  color: #94a3b8;
  font-size: 11px;
}

.synonym-decision-tree {
  min-width: 0;
  padding: 2px 4px 0;
}

.synonym-decision-tree ul {
  position: relative;
  display: flex;
  justify-content: center;
  margin: 0;
  padding: 18px 0 0;
}

.synonym-decision-tree > ul { padding-top: 0; }

.synonym-decision-tree li {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  padding: 18px 2px 0;
  list-style: none;
  text-align: center;
}

.synonym-decision-tree > ul > li { padding-top: 0; }

.synonym-decision-tree li::before,
.synonym-decision-tree li::after {
  content: "";
  position: absolute;
  top: 0;
  right: 50%;
  width: 50%;
  height: 18px;
  border-top: 1px solid rgba(148, 163, 184, 0.38);
}

.synonym-decision-tree li::after {
  right: auto;
  left: 50%;
  border-left: 1px solid rgba(148, 163, 184, 0.38);
}

.synonym-decision-tree li:only-child::before,
.synonym-decision-tree li:only-child::after { display: none; }
.synonym-decision-tree li:only-child { padding-top: 0; }
.synonym-decision-tree li:first-child::before,
.synonym-decision-tree li:last-child::after { border: 0; }
.synonym-decision-tree li:last-child::before {
  border-right: 1px solid rgba(148, 163, 184, 0.38);
  border-radius: 0 5px 0 0;
}
.synonym-decision-tree li:first-child::after { border-radius: 5px 0 0 0; }

.synonym-decision-tree ul ul::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 0;
  height: 18px;
  border-left: 1px solid rgba(148, 163, 184, 0.38);
}

.synonym-decision-node {
  display: inline-grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 1px 4px;
  align-items: center;
  min-width: 60px;
  max-width: 108px;
  padding: 5px 6px;
  border: 1px solid rgba(148, 163, 184, 0.3);
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.26);
  color: #94a3b8;
}

.synonym-decision-node > span {
  grid-row: 1 / span 2;
  font-size: 9px;
}

.synonym-decision-node strong {
  min-width: 0;
  color: inherit;
  font-size: 11px;
  overflow-wrap: anywhere;
}

.synonym-decision-node small {
  color: inherit;
  font-size: 9px;
  opacity: 0.82;
}

.synonym-decision-node.current {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.13);
  color: #fde68a;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.1);
}

.synonym-decision-node.explored {
  border-color: rgba(16, 185, 129, 0.52);
  background: rgba(16, 185, 129, 0.08);
  color: #a7f3d0;
}

.synonym-decision-node.root {
  min-width: 70px;
  border-color: #818cf8;
}

.synonym-decision-node.leaf { border-radius: 999px; }

.synonym-decision-note {
  margin-top: 7px;
  color: #64748b;
  font-size: 11px;
  text-align: center;
}

.synonym-groups {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 8px;
}

.synonym-group {
  display: grid;
  grid-template-columns: minmax(72px, auto) minmax(0, 1fr);
