  flex-direction: column;
  justify-content: center;
  min-width: 0;
  padding: 8px 9px;
  background: rgba(99, 102, 241, 0.13);
  border-right: 1px solid rgba(99, 102, 241, 0.22);
}

.synonym-group-root small {
  color: #818cf8;
  font-size: 9px;
}

.synonym-group-root strong {
  color: #c7d2fe;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.synonym-group-words {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
  padding: 8px;
}

.synonym-group-words span {
  padding: 4px 7px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 999px;
  color: #cbd5e1;
  font-size: 11px;
  overflow-wrap: anywhere;
}

.synonym-group-words span.active {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.12);
  color: #fde68a;
}

.synonym-groups-empty {
