  grid-template-rows: auto auto 1fr;
  gap: 7px;
  min-width: 0;
  min-height: 104px;
  padding: 8px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.3);
  text-align: center;
}

.synonym-word-slot.branch {
  border-color: rgba(16, 185, 129, 0.5);
  background: rgba(16, 185, 129, 0.07);
}

.synonym-word-slot.active {
  border-color: #f59e0b;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.12);
}

.synonym-word-slot.chosen {
  background: rgba(56, 189, 248, 0.08);
}

.synonym-word-slot.pending {
  opacity: 0.46;
}

.synonym-word-head {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  min-width: 0;
  color: #64748b;
  font-size: 9px;
}

.synonym-word-head span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.synonym-word-slot > strong {
  color: #f8fafc;
  font-size: 15px;
  overflow-wrap: anywhere;
}

.synonym-word-options {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  gap: 4px;
  flex-wrap: wrap;
}

.synonym-word-options span {
  padding: 2px 5px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 4px;
  color: #94a3b8;
  font-size: 9px;
  overflow-wrap: anywhere;
}

.synonym-word-options span.selected {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.13);
  color: #bae6fd;
}

.synonym-results-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 6px;
}

.synonym-result-legend {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 5px;
  color: #94a3b8;
  font-size: 9px;
}

.synonym-result-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.synonym-result-legend i {
  width: 14px;
  height: 10px;
  border-radius: 3px;
}

.synonym-result-legend i.original {
  border: 1px dashed #818cf8;
  background: rgba(99, 102, 241, 0.1);
}

.synonym-result-legend i.replaced {
  border: 1px solid #34d399;
  background: rgba(16, 185, 129, 0.18);
}

.synonym-result-item {
  display: grid;
  grid-template-columns: 25px minmax(0, 1fr);
  align-items: center;
  min-width: 0;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
  padding: 7px 3px;
  color: #cbd5e1;
  font-size: 11px;
}

.synonym-result-index {
  color: #64748b;
  font-size: 9px;
}

.synonym-result-sentence {
  line-height: 1.9;
  overflow-wrap: anywhere;
}

.synonym-result-word.replaceable {
  display: inline-block;
  margin: 1px 0;
  padding: 0 5px;
  border-radius: 4px;
  font-weight: 700;
  line-height: 1.45;
}

.synonym-result-word.original {
  border: 1px dashed #818cf8;
  background: rgba(99, 102, 241, 0.1);
  color: #c7d2fe;
}

.synonym-result-word.replaced {
  border: 1px solid #34d399;
  background: rgba(16, 185, 129, 0.18);
  color: #a7f3d0;
}

.synonym-result-item.newest {
  color: #a7f3d0;
  border-bottom-color: rgba(16, 185, 129, 0.45);
}

.synonym-results-empty {
  grid-column: 1 / -1;
  padding: 10px;
  color: #64748b;
  font-size: 11px;
  text-align: center;
}

[data-theme="light"] .synonym-sentence-viz { color: #1e293b; }
[data-theme="light"] .synonym-phase { color: #94a3b8; }
[data-theme="light"] .synonym-phase.active { color: #0369a1; }
