[data-theme="light"] .rw-trie-meta text {
  fill: #475569;
}

[data-theme="light"] .rw-trie-meta.terminal text,
[data-theme="light"] .rw-trie-meta .rw-trie-word {
  fill: #047857;
}

[data-theme="light"] .rw-root.active,
[data-theme="light"] .rw-result-token {
