  }

  .rw-section header span {
    text-align: left;
  }
}

/* ---- 2D prefix sum visualization ---- */
.prefix2d-viz {
  min-height: 300px;
  padding: 16px;
  display: grid;
  gap: 16px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.02);
}

.prefix2d-panels {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
}

.prefix2d-panels section {
  min-width: 0;
}

.prefix2d-heading {
  margin-bottom: 8px;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.prefix2d-table {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.prefix2d-axis,
.prefix2d-cell {
  min-width: 0;
  min-height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
}

.prefix2d-axis {
  min-height: 22px;
  color: #64748b;
  font-size: 11px;
  font-weight: 700;
}

.prefix2d-cell {
  position: relative;
  flex-direction: column;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(148, 163, 184, 0.08);
  color: #e2e8f0;
}

.prefix2d-cell strong {
  font-size: 14px;
  line-height: 1;
}

.prefix2d-cell small {
  max-width: 100%;
  margin-top: 3px;
  color: inherit;
  font-size: 11px;
  line-height: 1.05;
  text-align: center;
  white-space: nowrap;
}

.prefix2d-cell.in-region {
  border-color: rgba(16, 185, 129, 0.62);
  background: rgba(16, 185, 129, 0.17);
  color: #6ee7b7;
}

.prefix2d-cell.active {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.2);
  color: #fbbf24;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.12);
}

.prefix2d-cell.term-add {
  border-color: rgba(16, 185, 129, 0.68);
  background: rgba(16, 185, 129, 0.18);
  color: #6ee7b7;
}

.prefix2d-cell.term-subtract {
  border-color: rgba(239, 68, 68, 0.68);
  background: rgba(239, 68, 68, 0.17);
  color: #fca5a5;
}

.prefix2d-cell.term-mixed {
  border-color: rgba(99, 102, 241, 0.72);
  background: rgba(99, 102, 241, 0.18);
  color: #c7d2fe;
}

.prefix2d-status {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 8px;
}

.prefix2d-status div {
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.04);
}

.prefix2d-status span {
  display: block;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.prefix2d-status strong {
  display: block;
  margin-top: 3px;
  color: #f8fafc;
  font-size: 14px;
  overflow-wrap: anywhere;
}

/* ---- Prefix remainder visualization ---- */
.remainder-viz {
  min-height: 280px;
  padding: 16px;
  display: grid;
  gap: 16px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.02);
}

.tree-view:has(.prefix-count-viz) {
  min-height: 0;
  margin-top: 0;
  padding: 0;
  border: 0;
  background: transparent;
}

[data-theme="light"] .tree-view:has(.prefix-count-viz) {
  background: transparent;
  border-color: transparent;
}

.viz-right > .tree-view:has(~ .tree-view) {
  display: none !important;
}

.tree-view > .prefix-count-viz:not(:last-child) {
  display: none;
}

.tree-view > .prefix-count-guide {
  display: none;
}

.prefix-count-guide {
  display: grid;
  gap: 6px;
  padding: 12px 14px;
  border: 2px solid #d97706;
  border-radius: 7px;
  background: #3b2a12;
}

.prefix-count-guide strong {
  color: #fbbf24;
  font-size: 15px;
  font-weight: 800;
}

.prefix-count-guide span {
  color: #f8fafc;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.55;
}

.remainder-heading {
  margin-bottom: 8px;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.remainder-cells {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(72px, 1fr));
  gap: 8px;
}

.remainder-cell {
  min-width: 0;
  min-height: 98px;
  padding: 7px;
  display: grid;
  gap: 3px;
  place-items: center;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 7px;
  background: rgba(148, 163, 184, 0.07);
  color: #94a3b8;
}

.remainder-cell strong {
  color: #f8fafc;
  font-size: 18px;
}

.remainder-cell > span:not(.remainder-index) {
  font-size: 11px;
  white-space: nowrap;
}

.remainder-index {
  color: #64748b;
  font-size: 11px;
}

.remainder-cell.processed {
  border-color: rgba(99, 102, 241, 0.48);
  background: rgba(99, 102, 241, 0.11);
  color: #c7d2fe;
}

.remainder-cell.match {
  border-color: rgba(16, 185, 129, 0.62);
  background: rgba(16, 185, 129, 0.15);
  color: #6ee7b7;
}

.remainder-cell.match.too-short {
  border-color: rgba(244, 63, 94, 0.72);
  background: rgba(244, 63, 94, 0.14);
  color: #fda4af;
}

.remainder-cell.current {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.2);
  color: #fbbf24;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.12);
}

.remainder-cell.match.too-short.current {
  border-color: #f43f5e;
  background: rgba(244, 63, 94, 0.2);
  color: #fda4af;
  box-shadow: 0 0 0 2px rgba(244, 63, 94, 0.12);
}

.remainder-map {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
  gap: 8px;
}

.remainder-map-cell {
  min-width: 0;
  padding: 8px 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border: 1px solid rgba(99, 102, 241, 0.34);
  border-radius: 6px;
  background: rgba(99, 102, 241, 0.11);
  color: #c7d2fe;
}

.remainder-map-cell span,
.remainder-map-cell strong {
  font-size: 11px;
  overflow-wrap: anywhere;
}

.remainder-proof {
  padding: 12px;
  border: 1px solid rgba(99, 102, 241, 0.34);
  border-radius: 7px;
  background: rgba(99, 102, 241, 0.07);
}

.remainder-proof.valid {
  border-color: rgba(16, 185, 129, 0.48);
  background: rgba(16, 185, 129, 0.08);
}

.remainder-proof.too-short {
  border-color: rgba(244, 63, 94, 0.5);
  background: rgba(244, 63, 94, 0.08);
}

.remainder-proof-flow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 28px minmax(0, 1fr) 28px minmax(0, 1fr);
  gap: 8px;
  align-items: stretch;
}

.remainder-proof-term {
  min-width: 0;
  min-height: 86px;
  padding: 9px;
  display: grid;
  gap: 4px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.24);
  text-align: center;
}

.remainder-proof-term span,
.remainder-proof-term small {
  color: #94a3b8;
  font-size: 11px;
  overflow-wrap: anywhere;
}

.remainder-proof-term strong {
  color: #f8fafc;
  font-size: 15px;
  overflow-wrap: anywhere;
}

.remainder-proof-term.result {
  border-color: rgba(16, 185, 129, 0.42);
}

.remainder-proof.too-short .remainder-proof-term.result {
  border-color: rgba(244, 63, 94, 0.5);
}

.remainder-proof-operator {
  display: grid;
  place-items: center;
  color: #c7d2fe;
  font-size: 22px;
}

.remainder-proof-conclusion {
  margin-top: 9px;
  padding-top: 9px;
  border-top: 1px solid rgba(148, 163, 184, 0.18);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.45;
  text-align: center;
}

@media (max-width: 680px) {
  .remainder-proof-flow {
    grid-template-columns: minmax(0, 1fr);
  }

  .remainder-proof-operator {
    min-height: 20px;
  }
}

.remainder-status {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 8px;
}

.remainder-status div {
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.04);
}

.remainder-status span {
  display: block;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.remainder-status strong {
  display: block;
  margin-top: 3px;
  color: #f8fafc;
  font-size: 14px;
  overflow-wrap: anywhere;
}

/* ---- Difference array visualization ---- */
.diff-viz {
  min-height: 280px;
  padding: 18px;
  display: grid;
  gap: 16px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(99, 102, 241, 0.08), transparent 34%),
    rgba(15, 23, 42, 0.28);
}

.diff-heading {
