}

.diff-updates,
.diff-cells,
.diff-status {
  display: grid;
  gap: 10px;
}

.diff-updates {
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
}

.diff-cells {
  grid-template-columns: repeat(auto-fit, minmax(70px, 1fr));
}

.diff-update,
.diff-cell,
.diff-status div {
  min-width: 0;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.34);
}

.diff-update {
  padding: 10px;
  display: grid;
  gap: 8px;
}

.diff-update.current {
  border-color: rgba(245, 158, 11, 0.7);
  background: rgba(245, 158, 11, 0.13);
  box-shadow: 0 10px 22px rgba(245, 158, 11, 0.12);
}

.diff-update-index,
.diff-index,
.diff-status span {
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.diff-update-values {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}

.diff-update-values span {
  min-width: 0;
  padding: 6px 7px;
  display: grid;
  gap: 2px;
  border-radius: 6px;
  background: rgba(148, 163, 184, 0.09);
  color: #f8fafc;
  font-size: 13px;
  font-weight: 800;
  text-align: center;
}

.diff-update-values small {
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.diff-status strong {
  color: #f8fafc;
  font-size: 14px;
  overflow-wrap: anywhere;
}

.diff-cell {
  min-height: 86px;
  padding: 8px;
  display: grid;
  gap: 4px;
  place-items: center;
  color: #94a3b8;
}

.diff-value {
  color: #f8fafc;
  font-size: 21px;
  font-weight: 800;
  line-height: 1;
}

.diff-value.positive {
  color: #86efac;
}

.diff-value.negative {
  color: #fca5a5;
}

.diff-cell small {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.diff-cell.in-range {
  border-color: rgba(16, 185, 129, 0.46);
  background: rgba(16, 185, 129, 0.12);
}

.diff-cell.boundary {
  border-color: rgba(245, 158, 11, 0.72);
  background: rgba(245, 158, 11, 0.18);
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.12);
}

.diff-marker {
  padding: 2px 6px;
  border-radius: 999px;
  background: rgba(245, 158, 11, 0.18);
  color: #fbbf24;
}

.diff-cell.sentinel {
  border-style: dashed;
  opacity: 0.86;
}

.diff-cell.result {
  background: rgba(99, 102, 241, 0.13);
  border-color: rgba(129, 140, 248, 0.28);
}

.diff-status {
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
}

.diff-status div {
  padding: 8px 10px;
}

/* ---- Even/Odd slot fill visualization (LeetCode 767 approach 2) ---- */
.eof-viz {
  min-height: 220px;
  padding: 18px;
  background:
    linear-gradient(135deg, rgba(99, 102, 241, 0.08), transparent 36%),
    #0f172a;
  border-radius: 12px;
  border: 1px solid #334155;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.eof-heap-box {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 12px;
  color: #cbd5e1;
}

.eof-heap-label {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-right: 4px;
}

.eof-heap-entry {
  padding: 3px 8px;
  border-radius: 6px;
  background: rgba(148, 163, 184, 0.08);
  border: 1px solid rgba(148, 163, 184, 0.18);
}

.eof-heap-entry.root {
  background: rgba(245, 158, 11, 0.14);
  border-color: rgba(245, 158, 11, 0.5);
  color: #fbbf24;
}

.eof-heap-entry strong {
  text-transform: uppercase;
  font-size: 9px;
  margin-right: 3px;
}

.eof-heap-empty {
  color: #64748b;
  font-size: 12px;
}

.eof-current {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
}

.eof-current-label {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.eof-current strong {
  color: #fbbf24;
  font-size: 18px;
}

.eof-slots {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(48px, 1fr));
  gap: 6px;
}

.eof-slot {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 8px 4px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(148, 163, 184, 0.05);
}

.eof-slot.eof-even {
  border-color: rgba(56, 189, 248, 0.28);
  background: rgba(56, 189, 248, 0.06);
}

.eof-slot.eof-odd {
  border-color: rgba(192, 132, 252, 0.28);
  background: rgba(192, 132, 252, 0.06);
}

.eof-slot.eof-filled {
  border-color: rgba(16, 185, 129, 0.4);
  background: rgba(16, 185, 129, 0.08);
}

.eof-slot.eof-cursor {
  border-color: #f59e0b;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.3);
}

.eof-slot-index {
  color: #64748b;
  font-size: 9px;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
}

.eof-slot-char {
  color: #e2e8f0;
  font-size: 16px;
}

.eof-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  color: #94a3b8;
  font-size: 10px;
}

.eof-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.eof-swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 2px;
}

.eof-swatch-even { background: rgba(56, 189, 248, 0.5); border: 1px solid rgba(56, 189, 248, 0.7); }
.eof-swatch-odd { background: rgba(192, 132, 252, 0.5); border: 1px solid rgba(192, 132, 252, 0.7); }
.eof-swatch-cursor { background: rgba(245, 158, 11, 0.5); border: 1px solid #f59e0b; }

[data-theme="light"] .eof-viz {
  background: #f8fafc;
  border-color: #e2e8f0;
}

[data-theme="light"] .eof-heap-entry,
[data-theme="light"] .eof-slot {
  background: white;
  border-color: #cbd5e1;
}

[data-theme="light"] .eof-slot-char {
  color: #1e293b;
}

/* ---- Running sum visualization ---- */
.running-viz {
  min-height: 250px;
  padding: 18px;
  display: grid;
  gap: 16px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
