  background:
    linear-gradient(135deg, rgba(16, 185, 129, 0.08), transparent 35%),
    rgba(15, 23, 42, 0.28);
}

.running-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(92px, 1fr));
  gap: 10px;
}

.running-column {
  min-width: 0;
  padding: 10px;
  display: grid;
  gap: 7px;
  place-items: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.34);
}

.running-column.current {
  border-color: rgba(245, 158, 11, 0.74);
  background: rgba(245, 158, 11, 0.14);
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.12);
}

.running-column.done:not(.current) {
  border-color: rgba(16, 185, 129, 0.42);
  background: rgba(16, 185, 129, 0.1);
}

.running-index,
.running-input small,
.running-output small,
.running-status span {
