  border-radius: 999px;
  background: rgba(148, 163, 184, 0.1);
  color: #94a3b8;
  font-size: 14px;
  font-weight: 900;
}

.running-status {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 8px;
}

.running-status div {
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.34);
}

.running-status strong {
  display: block;
  margin-top: 3px;
  color: #f8fafc;
  font-size: 14px;
  overflow-wrap: anywhere;
}

/* ---- Digit podium visualization (e.g. bai 3536: max product of two digits) ---- */
.digit-podium-viz {
  min-height: 250px;
  padding: 20px;
  display: grid;
  gap: 22px;
  align-content: center;
  justify-content: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(99, 102, 241, 0.08), transparent 35%),
    rgba(15, 23, 42, 0.28);
}

.digit-strip {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

.digit-cell {
  width: 46px;
  padding: 8px 0;
  display: grid;
  gap: 4px;
  place-items: center;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.34);
  transition: transform 0.15s ease, background 0.15s ease, border-color 0.15s ease;
}

.digit-cell-idx {
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.digit-cell strong {
  color: #f8fafc;
  font-size: 19px;
  font-weight: 800;
  line-height: 1;
}

.digit-cell.current {
  border-color: rgba(245, 158, 11, 0.8);
  background: rgba(245, 158, 11, 0.16);
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.14);
  transform: translateY(-3px);
}

.digit-cell.done:not(.current) {
  border-color: rgba(148, 163, 184, 0.16);
  background: rgba(148, 163, 184, 0.06);
}

.digit-cell.done:not(.current) strong {
  color: #64748b;
}

.digit-podium {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 12px;
}

.digit-podium-op {
  align-self: center;
  color: #94a3b8;
  font-size: 20px;
  font-weight: 800;
}

.digit-slot {
  width: 96px;
  padding: 12px 8px;
  display: grid;
  gap: 6px;
  place-items: center;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.34);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.digit-slot-label {
  color: #94a3b8;
  font-size: 9.5px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-align: center;
}

.digit-slot strong {
  color: #f8fafc;
  font-size: 26px;
  font-weight: 800;
  line-height: 1;
}

.digit-slot-first {
  border-color: rgba(34, 197, 94, 0.5);
  background: rgba(34, 197, 94, 0.12);
}

.digit-slot-second {
  border-color: rgba(99, 102, 241, 0.5);
  background: rgba(99, 102, 241, 0.14);
}

.digit-slot-answer {
  border-color: rgba(245, 158, 11, 0.55);
  background: rgba(245, 158, 11, 0.14);
}

.digit-slot.bump {
  transform: translateY(-4px) scale(1.06);
  box-shadow: 0 0 0 3px rgba(251, 191, 36, 0.28);
}

.multi-slot-podium {
  flex-wrap: wrap;
  gap: 10px;
}

.multi-slot-podium .digit-slot {
  width: 88px;
}

.multi-slot-groups {
  display: grid;
  gap: 14px;
}

.multi-slot-group {
  display: grid;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px dashed rgba(148, 163, 184, 0.22);
}

.multi-slot-group-heading {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.multi-slot-group-cells {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.multi-slot-group-cells .digit-slot {
  width: 108px;
  position: relative;
}

.digit-slot-transition {
  color: #fbbf24;
  font-size: 10px;
  font-weight: 700;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  white-space: nowrap;
}

.multi-slot-mirror-hint {
  text-align: center;
  color: #818cf8;
  font-size: 11px;
  font-weight: 700;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(99, 102, 241, 0.1);
  border: 1px solid rgba(99, 102, 241, 0.25);
  justify-self: center;
}

