.tri-ptr-right { color: #a78bfa; }
.tri-ptr-k { color: #34d399; }
.tri-cell { width: 48px; padding: 8px 0; display: grid; gap: 4px; place-items: center; border: 1px solid rgba(148, 163, 184, 0.22); border-radius: 8px; background: rgba(15, 23, 42, 0.34); }
.tri-cell span { color: #94a3b8; font-size: 9px; font-weight: 800; }
.tri-cell strong { color: #f8fafc; font-size: 18px; line-height: 1; }
.tri-cell-active { border-color: rgba(56, 189, 248, 0.78); box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.14); transform: translateY(-2px); }
.tri-cell-counted { border-color: rgba(34, 197, 94, 0.72); background: rgba(34, 197, 94, 0.14); }
.tri-panels { display: grid; grid-template-columns: minmax(0, 1fr) minmax(120px, auto); gap: 10px; }
.tri-formula, .tri-count { padding: 11px 14px; display: grid; gap: 3px; border: 1px solid rgba(148, 163, 184, 0.2); border-radius: 8px; background: rgba(15, 23, 42, 0.3); text-align: center; }
