/* ---- 1D prefix sum visualization ---- */
.prefix1d-viz {
  min-height: 260px;
  padding: 18px;
  display: grid;
  gap: 16px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(99, 102, 241, 0.08), transparent 36%),
    rgba(15, 23, 42, 0.28);
}

.prefix1d-heading {
  margin-bottom: 8px;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.prefix1d-row,
.prefix1d-status {
  display: grid;
  gap: 8px;
}

.prefix1d-row {
  grid-template-columns: repeat(auto-fit, minmax(68px, 1fr));
}

.prefix1d-cell,
.prefix1d-status div {
  min-width: 0;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.34);
}

.prefix1d-cell {
  min-height: 72px;
  padding: 8px;
  display: grid;
  gap: 4px;
  place-items: center;
}

.prefix1d-cell span,
.prefix1d-cell small,
.prefix1d-status span {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.prefix1d-cell strong,
.prefix1d-status strong {
  color: #f8fafc;
  font-size: 19px;
  font-weight: 800;
  line-height: 1;
  overflow-wrap: anywhere;
}

.prefix1d-cell.current {
  border-color: rgba(245, 158, 11, 0.74);
  background: rgba(245, 158, 11, 0.16);
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.12);
}

.prefix1d-cell.in-query {
  border-color: rgba(16, 185, 129, 0.48);
  background: rgba(16, 185, 129, 0.12);
}

.prefix1d-cell.edge {
  border-color: rgba(99, 102, 241, 0.7);
  background: rgba(99, 102, 241, 0.18);
}

.prefix1d-cell.excluded-left {
  border-color: rgba(248, 113, 113, 0.38);
  background: rgba(239, 68, 68, 0.08);
}

.prefix1d-cell.excluded-left strong {
  color: #fecaca;
}

.prefix1d-cell small {
  min-height: 12px;
  text-align: center;
  overflow-wrap: anywhere;
  letter-spacing: 0;
  text-transform: none;
}

.prefix1d-proof {
  display: grid;
  gap: 10px;
  min-width: 0;
  padding: 12px;
  border: 1px solid rgba(99, 102, 241, 0.3);
  border-radius: 8px;
  background: rgba(99, 102, 241, 0.1);
}

.prefix1d-proof-title {
  color: #c7d2fe;
  font-size: 12px;
  font-weight: 850;
  text-transform: uppercase;
}

.prefix1d-formula {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}

.prefix1d-formula > span {
  display: grid;
  gap: 4px;
  min-width: 118px;
  padding: 9px 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.34);
}

.prefix1d-formula > strong {
  display: grid;
  place-items: center;
  color: #cbd5e1;
  font-size: 22px;
}

.prefix1d-formula small {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
}

.prefix1d-formula b {
  color: #f8fafc;
  font-size: 20px;
}

.prefix1d-formula .take {
  border-color: rgba(16, 185, 129, 0.48);
  background: rgba(16, 185, 129, 0.12);
}

.prefix1d-formula .drop {
  border-color: rgba(248, 113, 113, 0.4);
  background: rgba(239, 68, 68, 0.1);
}

.prefix1d-formula .answer {
  border-color: rgba(245, 158, 11, 0.5);
  background: rgba(245, 158, 11, 0.12);
}

.prefix1d-formula > span.is-active {
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.16);
  transform: translateY(-2px);
}

.prefix1d-proof:not(.phase-subtract) .prefix1d-formula .answer b,
.prefix1d-proof.phase-select-range .prefix1d-formula .take b,
.prefix1d-proof.phase-select-range .prefix1d-formula .drop b,
.prefix1d-proof.phase-right-prefix .prefix1d-formula .drop b {
  color: #64748b;
}

.prefix1d-proof-detail {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.prefix1d-proof-detail span {
  min-width: 0;
  color: #cbd5e1;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.prefix1d-status {
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
}

.prefix1d-status div {
  padding: 8px 10px;
}

.prefix1d-status strong {
  display: block;
  margin-top: 3px;
  font-size: 14px;
}

