.trap-bar,
.trap-water {
  display: grid;
  place-items: center;
  min-height: 0;
  border-radius: 5px 5px 0 0;
}

.trap-bar {
  height: var(--land);
  border: 1px solid rgba(148, 163, 184, 0.42);
  background: linear-gradient(180deg, #64748b, #334155);
}

.trap-water {
  height: var(--water);
  border: 1px solid rgba(56, 189, 248, 0.58);
  border-bottom: 0;
  background: linear-gradient(180deg, rgba(56, 189, 248, 0.58), rgba(14, 165, 233, 0.26));
}

.trap-bar b,
.trap-water b {
  color: #f8fafc;
