  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 10px;
  font-weight: 800;
  text-align: center;
}

.trap-pointer-row {
  display: flex;
  min-height: 20px;
  justify-content: center;
  gap: 4px;
}

.trap-pointer {
  display: inline-grid;
  width: 20px;
  height: 20px;
  place-items: center;
  border-radius: 999px;
  color: #0f172a;
  font-size: 11px;
  font-weight: 900;
}

.trap-pointer.left {
  background: #fbbf24;
}

.trap-pointer.right {
  background: #38bdf8;
}

.trap-cell.current .trap-tank {
  outline: 2px solid rgba(245, 158, 11, 0.68);
  outline-offset: 3px;
  border-radius: 6px;
}

.trap-cell.has-water .trap-index {
  color: #7dd3fc;
}

.trap-formula {
  display: grid;
  gap: 4px;
  border-color: rgba(14, 165, 233, 0.36);
  background: rgba(14, 165, 233, 0.1);
}

.trap-formula.positive {
  border-color: rgba(16, 185, 129, 0.46);
  background: rgba(16, 185, 129, 0.1);
}

.trap-formula span {
  color: #cbd5e1;
  font-size: 12px;
}

.trap-viz.compact .trap-summary {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.trap-viz.compact .trap-summary small {
  font-size: 9px;
}

.trap-viz.compact .trap-summary b {
  font-size: 18px;
}

.trap-viz.compact .trap-chart {
  grid-template-columns: repeat(var(--trap-cols), minmax(24px, 1fr));
  gap: 4px;
  min-height: 185px;
}

.trap-viz.compact .trap-tank {
  height: 145px;
}

.trap-viz.compact .trap-bar,
.trap-viz.compact .trap-water {
  border-radius: 4px 4px 0 0;
}

.trap-viz.compact .trap-index {
  font-size: 9px;
}

.trap-viz.compact .trap-pointer {
  width: 18px;
  height: 18px;
  font-size: 10px;
}

