/* ---- Trapping Rain Water II visualization (#407) ---- */
.rain2-viz {
  display: grid;
  gap: 10px;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  padding: 12px;
  border: 1px solid rgba(56, 189, 248, 0.2);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(14, 165, 233, 0.1), transparent 42%),
    rgba(15, 23, 42, 0.3);
}

.rain2-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 8px;
  min-width: 0;
}

.rain2-summary span,
.rain2-action,
.rain2-formula,
.rain2-heap,
.rain2-status span,
.rain2-grid-card {
  min-width: 0;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.34);
}

.rain2-summary span {
  padding: 8px 10px;
}

.rain2-summary small,
.rain2-action small,
.rain2-formula small,
.rain2-status small,
.rain2-heap small,
.rain2-grid-card header span {
  display: block;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 850;
  text-transform: uppercase;
}

.rain2-summary strong,
.rain2-action strong,
.rain2-formula strong,
.rain2-status strong,
.rain2-heap strong,
.rain2-grid-card header strong {
  display: block;
  color: #f8fafc;
  font-weight: 850;
  overflow-wrap: anywhere;
}

.rain2-summary strong {
  margin-top: 3px;
  font-size: 22px;
}

.rain2-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  min-width: 0;
}

.rain2-grid-card {
  display: grid;
  gap: 10px;
  overflow: hidden;
  padding: 10px;
}

.rain2-grid-card header {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: baseline;
}

.rain2-grid {
  display: grid;
  grid-template-columns: repeat(var(--rain2-cols), minmax(36px, 1fr));
  gap: 5px;
  width: 100%;
  min-width: 0;
}

.rain2-cell {
  position: relative;
  display: grid;
  align-content: end;
  min-width: 0;
  min-height: 86px;
  padding: 7px 4px 5px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.42);
