}

.rain2-cell.has-water {
  background: rgba(14, 165, 233, 0.14);
}

.rain2-coord {
  position: absolute;
  top: 5px;
  left: 6px;
  z-index: 2;
  color: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 10px;
  font-weight: 800;
}

.rain2-column {
  position: relative;
  display: grid;
  align-content: end;
  justify-items: center;
  height: 62px;
  min-width: 0;
  border-bottom: 2px solid rgba(148, 163, 184, 0.28);
}

.rain2-column b {
  display: grid;
  place-items: center;
  width: 100%;
  height: var(--rain2-height);
  min-height: 12px;
  border: 1px solid rgba(148, 163, 184, 0.4);
  border-radius: 5px 5px 0 0;
  background: linear-gradient(180deg, #64748b, #334155);
  color: #f8fafc;
  font-size: 11px;
  text-shadow: 0 1px 1px rgba(15, 23, 42, 0.45);
}

.rain2-water {
  display: grid;
  place-items: center;
  width: 100%;
  height: var(--rain2-water);
  min-height: 0;
  border: 1px solid rgba(56, 189, 248, 0.65);
  border-bottom: 0;
  border-radius: 5px 5px 0 0;
  background: linear-gradient(180deg, rgba(125, 211, 252, 0.74), rgba(14, 165, 233, 0.32));
  color: #e0f2fe;
  font-size: 11px;
  font-style: normal;
  font-weight: 900;
}

.rain2-side {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.rain2-heap,
.rain2-status {
  grid-column: 1 / -1;
}

.rain2-action,
.rain2-formula,
.rain2-heap {
  display: grid;
  gap: 5px;
  padding: 9px 10px;
}

.rain2-action {
  border-color: rgba(245, 158, 11, 0.38);
  background: rgba(245, 158, 11, 0.1);
}

.rain2-formula {
  border-color: rgba(14, 165, 233, 0.38);
