}

.rain2-heap header {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: baseline;
}

.rain2-heap > div {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.rain2-heap span,
.rain2-heap-empty,
.rain2-more {
  display: inline-grid;
  gap: 1px;
  min-width: 54px;
  padding: 5px 6px;
  border-radius: 6px;
  background: rgba(148, 163, 184, 0.14);
  color: #cbd5e1;
  font-size: 11px;
}

.rain2-heap span.is-top {
  background: rgba(245, 158, 11, 0.18);
  color: #fef3c7;
}

.rain2-heap em {
  color: #94a3b8;
  font-style: normal;
}

.rain2-status {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(92px, 1fr));
  gap: 6px;
}

.rain2-status span {
  padding: 7px 8px;
}

.rain2-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
}

.rain2-legend span {
  display: inline-flex;
  gap: 5px;
  align-items: center;
}

.rain2-legend i {
  width: 11px;
  height: 11px;
  border-radius: 3px;
  border: 1px solid rgba(148, 163, 184, 0.34);
}

.rain2-legend .border { background: rgba(56, 189, 248, 0.28); }
.rain2-legend .popped { background: rgba(245, 158, 11, 0.75); }
.rain2-legend .neighbor { background: rgba(34, 197, 94, 0.72); }
.rain2-legend .water { background: rgba(14, 165, 233, 0.72); }

@media (max-width: 760px) {
  .rain2-summary,
  .rain2-side {
    grid-template-columns: 1fr;
  }

  .rain2-grid {
    grid-template-columns: repeat(var(--rain2-cols), minmax(28px, 1fr));
    gap: 4px;
  }

  .rain2-cell {
    min-height: 74px;
  }

  .rain2-column {
    height: 52px;
  }
}

/* LeetCode #4013 — transformed prefixes and Fenwick rank counting. */
.even-odd-ratio-viz {
  box-sizing: border-box;
  display: grid;
  gap: 10px;
  width: 100%;
  min-width: 0;
  padding: 12px;
  color: #e2e8f0;
}

.even-odd-ratio-viz * { box-sizing: border-box; }

.even-odd-ratio-phases {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-bottom: 1px solid rgba(148, 163, 184, 0.22);
}

.even-odd-ratio-phases span {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 0;
  padding: 7px 4px;
  color: #64748b;
  text-align: center;
}

.even-odd-ratio-phases span.is-active {
  border-bottom: 3px solid #22d3ee;
  color: #e2e8f0;
}

.even-odd-ratio-phases span.is-done { color: #6ee7b7; }
.even-odd-ratio-phases b { font-size: 10px; font-weight: 500; overflow-wrap: anywhere; }

.even-odd-ratio-formula {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 7px;
  min-width: 0;
  padding: 8px 9px;
  border-left: 4px solid #22d3ee;
  background: rgba(8, 145, 178, 0.08);
}

.even-odd-ratio-formula > span {
  display: inline-grid;
  grid-template-columns: auto auto;
  align-items: center;
  gap: 5px;
  padding: 4px 7px;
  border: 1px solid #475569;
  border-radius: 5px;
  background: rgba(15, 23, 42, 0.34);
}

.even-odd-ratio-formula > span.is-even { border-color: #d97706; }
.even-odd-ratio-formula > span.is-odd { border-color: #8b5cf6; }
.even-odd-ratio-formula small { color: #94a3b8; font-size: 8px; font-weight: 500; }
.even-odd-ratio-formula strong { color: #f8fafc; font: 500 11px/1 ui-monospace, SFMono-Regular, Menlo, monospace; }
.even-odd-ratio-formula > i { color: #64748b; font-style: normal; }
.even-odd-ratio-formula > code {
  min-width: 0;
