.cs315-ranks, .cs315-nums, .cs315-bits { display: flex; gap: 7px; overflow-x: auto; padding: 3px 2px 7px; }
.cs315-rank {
  flex: 1 0 58px; min-height: 50px; display: grid; place-items: center; align-content: center; gap: 2px;
  border: 1px solid rgba(148, 163, 184, 0.22); border-radius: 8px; background: rgba(15, 23, 42, 0.4);
}
.cs315-rank small { color: #cbd5e1; font-size: 12px; }
.cs315-rank strong { color: #94a3b8; font-size: 11px; }
.cs315-rank.smaller { border-color: rgba(16, 185, 129, 0.48); background: rgba(16, 185, 129, 0.08); }
.cs315-rank.active { border-color: #f59e0b; background: rgba(245, 158, 11, 0.15); box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.1); }
.cs315-num {
