/* ---- Fenwick Tree visualization ---- */
.fenwick-viz {
  min-height: 280px;
  padding: 18px;
  display: grid;
  gap: 14px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.28);
}

.fenwick-mode {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
  min-width: 0;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
}

.fenwick-mode span {
  padding: 3px 7px;
  border-radius: 5px;
  background: rgba(99, 102, 241, 0.18);
  color: #c7d2fe;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.fenwick-mode strong {
  min-width: 0;
  color: #cbd5e1;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.fenwick-scroll {
  overflow-x: auto;
  padding-bottom: 4px;
}

.fenwick-content {
  min-width: var(--fenwick-min-width);
  display: grid;
  gap: 8px;
}

.fenwick-heading {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.fenwick-row {
  display: grid;
  grid-template-columns: repeat(var(--fenwick-cols), minmax(68px, 1fr));
  gap: 8px;
}

.fenwick-cell {
  min-width: 0;
  min-height: 72px;
  padding: 7px 6px;
  display: grid;
  place-items: center;
  gap: 3px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.38);
  transition: border-color 0.2s ease, background-color 0.2s ease, box-shadow 0.2s ease;
}

.fenwick-cell span,
.fenwick-cell small,
.fenwick-status span {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 700;
}

.fenwick-cell strong,
.fenwick-status strong {
  color: #f8fafc;
  font-size: 18px;
  font-weight: 800;
  line-height: 1;
  overflow-wrap: anywhere;
}

.fenwick-cell small {
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
}

.fenwick-cell.visited:not(.active) {
  border-color: rgba(99, 102, 241, 0.48);
  background: rgba(99, 102, 241, 0.1);
}

.fenwick-viz.mode-build .fenwick-cell.active,
.fenwick-viz.mode-update .fenwick-cell.active {
  border-color: rgba(245, 158, 11, 0.8);
  background: rgba(245, 158, 11, 0.16);
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.12);
}

.fenwick-viz.mode-query .fenwick-cell.active {
  border-color: rgba(16, 185, 129, 0.76);
  background: rgba(16, 185, 129, 0.15);
  box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.1);
}

.fenwick-status {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 8px;
}

.fenwick-status div {
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.34);
}

.fenwick-status strong {
  display: block;
  margin-top: 3px;
  font-size: 14px;
}

[data-theme="light"] .fenwick-viz {
  background: #f8fafc;
  border-color: #e2e8f0;
}

[data-theme="light"] .fenwick-mode span {
  background: #e0e7ff;
  color: #4338ca;
}

[data-theme="light"] .fenwick-mode strong,
[data-theme="light"] .fenwick-heading,
[data-theme="light"] .fenwick-cell span,
[data-theme="light"] .fenwick-cell small,
[data-theme="light"] .fenwick-status span {
