/* ---- Variables panel ---- */
.vars-panel {
  margin-top: 16px;
  padding: 12px 16px;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
}

.vars-head {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #64748b;
  margin-bottom: 10px;
}

.watch-row {
  display: flex;
  gap: 8px;
  margin-bottom: 10px;
}

.watch-row input {
  min-width: 220px;
  flex: 1;
  padding: 8px 10px;
