  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.var-item .var-name {
  color: #a5b4fc;
  font-weight: 700;
}

.var-item .var-eq {
  color: #64748b;
}

.var-item .var-value {
