  font-weight: 700;
}

/* ---- Code panel ---- */
.code-panel {
  margin: 0;
  padding: 14px 0;
  background: rgba(15, 10, 30, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 14px;
  overflow-x: auto;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  max-height: 420px;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  font-variant-ligatures: none;
  font-feature-settings: "liga" 0, "calt" 0;
  font-size: 11.5px;
  line-height: 1.55;
  position: sticky;
  top: 0;
  backdrop-filter: blur(12px);
  /* Prevent iOS rendering bugs with sticky + overflow */
  -webkit-transform: translateZ(0);
  transform: translateZ(0);
  /* Belt-and-braces: keep iOS Safari from auto-inflating long lines. */
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

/* #685 has a compact, 25-line implementation: show all of it without an
   internal scrollbar so the page remains the single scroll surface. */
.viz-split.problem-685-layout .code-panel {
  height: auto;
  max-height: none;
  overflow-y: visible;
}

/* #2101 benefits from a wider canvas for its radius map and directed graph. */
@media (min-width: 769px) {
  .viz-split.problem-2101-layout .viz-left { flex-basis: 36%; }
}

/* #2058 has a long linked-list trace. Keep code and visualization as separate
   rows so the list can use the full panel width. */
@media (min-width: 769px) {
  .viz-split.problem-2058-layout {
    flex-direction: column;
    align-items: stretch;
  }

  .viz-split.problem-2058-layout .viz-left,
  .viz-split.problem-2058-layout .viz-right {
    flex: none;
    width: 100%;
  }

  .viz-split.problem-2058-layout .code-panel {
    position: relative;
    max-height: 360px;
  }

  .viz-split.problem-2058-layout .tree-view {
    min-height: 180px;
    overflow-x: auto;
  }
}

/* LeetCode 173, 211, 212, 642 and 648: grow the code pane with taller tree/trie debug views. */
@media (min-width: 769px) {
  .viz-split.problem-173-layout,
  .viz-split.problem-211-layout,
  .viz-split.problem-212-layout,
  .viz-split.problem-642-layout,
  .viz-split.problem-648-layout {
    align-items: stretch;
  }

  .viz-split.problem-173-layout .viz-left,
  .viz-split.problem-211-layout .viz-left,
  .viz-split.problem-212-layout .viz-left,
  .viz-split.problem-642-layout .viz-left,
  .viz-split.problem-648-layout .viz-left {
    display: flex;
    flex-direction: column;
  }

  .viz-split.problem-173-layout .code-panel,
  .viz-split.problem-211-layout .code-panel,
  .viz-split.problem-212-layout .code-panel,
  .viz-split.problem-642-layout .code-panel,
  .viz-split.problem-648-layout .code-panel {
    flex: 1 1 auto;
    height: auto;
    min-height: 680px;
    max-height: none;
  }
}

.code-line {
  display: flex;
  padding: 0 14px;
  white-space: pre;
  color: #cdd6f4;
  width: max-content;
  min-width: 100%;
  box-sizing: border-box;
  transition: background-color 0.2s ease, box-shadow 0.2s ease, color 0.2s ease;
  position: relative;
}

.code-line .ln {
  display: inline-block;
  width: 28px;
  margin-right: 12px;
  text-align: right;
  color: #45475a;
  flex-shrink: 0;
  -webkit-user-select: none;
  user-select: none;
  transition: color 0.2s ease, font-weight 0.2s ease;
  cursor: pointer;
}

.code-line .breakpoint-dot {
  position: absolute;
  left: 6px;
  top: 50%;
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: #ef4444;
  box-shadow: 0 0 0 1px rgba(127, 29, 29, 0.5);
  opacity: 0;
  transform: translateY(-50%);
  transition: opacity 0.15s ease, transform 0.15s ease;
  cursor: pointer;
}

.code-line:hover .breakpoint-dot {
  opacity: 0.35;
}

.code-line.has-breakpoint .breakpoint-dot {
  opacity: 1;
}

.code-line.has-breakpoint .breakpoint-dot:hover {
  transform: translateY(-50%) scale(1.12);
}

/* Indent guide: subtle vertical dashed line at each 4-column indent level.
   Each guide span occupies exactly 4 monospace characters and carries a
   left border, so the guide sits on the left edge of that indent level. */
.code-line .indent-guide {
  display: inline-block;
  width: 4ch;
  border-left: 1px dashed rgba(180, 190, 210, 0.18);
  vertical-align: top;
  white-space: pre;
  /* The border is drawn on the left edge; the space that precedes it in the
     line is provided by the previous guide (or, for the first guide, by the
     .txt element's own start). */
}

/* Highlight the guides that are inside the currently-active line so it's
   easy to trace where you are in a nested block. */
.code-line.active .indent-guide {
  border-left-color: rgba(249, 115, 22, 0.45);
}

.code-line .txt {
  flex: 0 0 auto;
  white-space: pre;
}

.code-line.active {
  background: rgba(249, 115, 22, 0.1);
  box-shadow: inset 3px 0 0 #f97316;
  animation: highlightPulse 0.3s ease-out;
}

.code-line.active .ln {
  color: #f97316;
  font-weight: 700;
}

/* Line-by-line debug mode: execution marker */
.code-line.active::before {
  content: "▶";
  position: absolute;
  left: 24px;
  top: 50%;
  width: 12px;
  color: #f97316;
  font-size: 10px;
  line-height: 1;
  transform: translateY(-50%);
  animation: executeArrow 0.4s ease-in-out;
  pointer-events: none;
}

@keyframes highlightPulse {
  0% {
    background: rgba(249, 115, 22, 0.25);
    box-shadow: inset 3px 0 0 #f97316, 0 0 8px rgba(249, 115, 22, 0.5);
  }
  100% {
    background: rgba(249, 115, 22, 0.1);
    box-shadow: inset 3px 0 0 #f97316;
  }
}

@keyframes executeArrow {
  0% {
    opacity: 0;
    transform: translate(-8px, -50%);
  }
  50% {
    opacity: 1;
  }
  100% {
    opacity: 1;
    transform: translate(0, -50%);
  }
}

.code-section-label {
