.rsv-bfs-guide {
  min-width: 0;
  margin-bottom: 14px;
  display: grid;
  gap: 10px;
  color: #e2e8f0;
}

.rsv-bfs-phases {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
}

.rsv-bfs-phases > span {
  min-width: 0;
  min-height: 38px;
