  gap: 7px;
  border-bottom: 3px solid rgba(148, 163, 184, 0.22);
  color: #64748b;
  font-size: 9px;
}

.rsv-bfs-phases > span b {
  min-width: 0;
  overflow-wrap: anywhere;
}

.rsv-bfs-phases > span.is-active {
  border-color: #f59e0b;
  color: #f8fafc;
