  align-items: stretch;
  gap: 8px;
}

.rsv-level-flow > b {
  align-self: center;
  color: #f59e0b;
  font-size: 20px;
}

.rsv-level-band {
  min-width: 0;
  padding: 9px;
  display: grid;
  gap: 8px;
