  gap: 8px;
}

.rsv-level-band header strong {
  color: #f8fafc;
  font-size: 9px;
}

.rsv-level-band header span {
  min-width: 0;
  color: #64748b;
  font-size: 8px;
  text-align: right;
  overflow-wrap: anywhere;
}

.rsv-level-band > div {
  min-width: 0;
  display: flex;
  align-items: stretch;
  gap: 6px;
  overflow-x: auto;
}

.rsv-level-node,
.rsv-next-node {
  position: relative;
  flex: 0 0 72px;
  min-height: 62px;
  padding: 5px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 5px;
  background: rgba(15, 23, 42, 0.3);
}

.rsv-level-node small,
