  .rsv-level-flow > b {
    justify-self: center;
    transform: rotate(90deg);
  }

  .tree-queue-layout {
    grid-template-columns: 1fr;
  }

  .queue-viz-compact .queue-cells {
    grid-template-columns: repeat(auto-fit, minmax(64px, 1fr));
  }

  .tree-queue-stacked .queue-viz-compact .queue-cells,
  .tree-queue-stacked .queue-viz-compact .queue-status {
    grid-template-columns: repeat(2, minmax(90px, 1fr));
  }
}

@media (max-width: 680px) {
  .rsv-bfs-phases,
  .rsv-bfs-status,
  .rsv-dfs-phases,
  .rsv-dfs-status {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rsv-level-band header {
    align-items: flex-start;
    flex-direction: column;
  }

  .rsv-level-band header span {
    text-align: left;
  }

  .rsv-bfs-decision {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .rsv-bfs-decision span,
  .rsv-dfs-decision span {
    grid-column: 1 / -1;
  }

  .rsv-dfs-decision {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .rsv-dfs-stack header,
  .rsv-dfs-depths header,
  .rsv-dfs-traversal {
    align-items: flex-start;
    flex-direction: column;
  }

  .rsv-result {
    align-items: flex-start;
    flex-direction: column;
  }

  .distance-k-phases {
    grid-template-columns: 1fr;
  }

  .distance-k-layer {
    grid-template-columns: 72px minmax(0, 1fr);
  }
}

.tree-svg {
  display: block;
  margin: 0 auto;
}

.tree-svg.tree-svg-fit {
  max-width: 100%;
  height: auto;
}

.tree-edge {
  stroke: #94a3b8;
  stroke-width: 2.6;
}

.tree-arrow {
  fill: #94a3b8;
}

.tree-edge.null-edge {
  stroke-dasharray: 4 4;
  opacity: 0.38;
}

.tree-node circle,
.tree-node rect {
  fill: #111827;
  stroke: #94a3b8;
  stroke-width: 2.4;
  transition: stroke 0.25s, fill 0.25s;
}

.tree-node text {
  fill: #f8fafc;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 15px;
  font-weight: 800;
}

.tree-node.word circle,
.tree-node.word rect {
  fill: rgba(16, 185, 129, 0.22);
  stroke: #34d399;
  stroke-width: 2.6;
}

.tree-node .tree-ring {
  fill: none;
  stroke: #10b981;
  stroke-width: 1.5;
  opacity: 0.55;
}

.tree-node.hl circle,
.tree-node.hl rect {
  stroke: #f59e0b;
  stroke-width: 3;
  fill: rgba(245, 158, 11, 0.1);
}

.tree-node.hl text {
  fill: #fbbf24;
}

.tree-node.pruned circle,
.tree-node.pruned rect {
  fill: rgba(239, 68, 68, 0.1);
  stroke: #ef4444;
  stroke-dasharray: 4 3;
}

.tree-node.pruned text {
  fill: #fca5a5;
}

.tree-node.null circle,
.tree-node.null rect {
  fill: rgba(100, 116, 139, 0.05);
  stroke: #64748b;
  stroke-width: 1.5;
  stroke-dasharray: 4 3;
  opacity: 0.55;
}

.tree-node.null > text:not(.tree-annotation) {
  fill: #94a3b8;
  font-size: 11px;
  font-weight: 600;
  opacity: 0.7;
}

.tree-sub {
  fill: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 10px;
  font-weight: 600;
}

.tree-level-label {
  fill: #a5b4fc;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
  opacity: 1;
}

.tree-annotation {
  fill: #818cf8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 11px;
  font-weight: 700;
}

.tree-annotation.left { fill: #38bdf8; }
.tree-annotation.right { fill: #c084fc; }
.tree-annotation.left-done { fill: #22d3ee; }
.tree-annotation.right-done { fill: #a78bfa; }
.tree-annotation.pending { fill: #64748b; }
.tree-annotation.parent { fill: #94a3b8; }
.tree-annotation.root,
.tree-annotation.node { fill: #fbbf24; }

[data-theme="light"] .tree-annotation.left { fill: #0369a1; }
[data-theme="light"] .tree-annotation.right { fill: #7e22ce; }
[data-theme="light"] .tree-annotation.left-done { fill: #0e7490; }
[data-theme="light"] .tree-annotation.right-done { fill: #6d28d9; }
[data-theme="light"] .tree-annotation.pending { fill: #94a3b8; }
[data-theme="light"] .tree-annotation.parent { fill: #64748b; }
[data-theme="light"] .tree-annotation.root,
[data-theme="light"] .tree-annotation.node { fill: #b45309; }

/* ---- Lowest Common Ancestor of Deepest Leaves (#1123) ---- */
.lca-deepest-guide {
  display: grid;
  gap: 10px;
  margin-bottom: 12px;
  color: #e2e8f0;
}

.tree-svg.lca-deepest-tree {
  max-width: 100%;
  height: auto;
}

.lca-contract {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  align-items: center;
  padding: 9px 11px;
  border-left: 4px solid #818cf8;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.72);
}

.lca-contract strong,
.lca-contract code {
  color: #f8fafc;
}

.lca-contract small {
  flex: 1 1 250px;
  color: #94a3b8;
}

.lca-stack-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px 12px;
  align-items: center;
}

.lca-stack-row > b,
.lca-progress-label {
  color: #94a3b8;
  font-size: 10px;
  letter-spacing: 0.08em;
}

.lca-stack-row > div {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  align-items: center;
  min-width: 0;
}

.lca-stack-node {
  padding: 4px 7px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  border-radius: 6px;
  background: rgba(30, 41, 59, 0.7);
  color: #cbd5e1;
  font: 11px "SFMono-Regular", Consolas, monospace;
}

.lca-stack-node.current {
  border-color: #f59e0b;
  color: #fbbf24;
}

.lca-stack-row i,
.lca-stack-empty {
  color: #64748b;
  font-size: 11px;
}

.lca-compare-row {
  display: grid;
  grid-template-columns: minmax(110px, 1fr) minmax(180px, 1.5fr) minmax(110px, 1fr) minmax(110px, 0.9fr);
  gap: 8px;
  align-items: stretch;
}

.lca-side,
.lca-decision,
.lca-result {
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 9px;
  background: rgba(30, 41, 59, 0.62);
}

.lca-side,
.lca-result {
  display: grid;
  gap: 3px;
  align-content: center;
  text-align: center;
}

.lca-side small,
.lca-result small {
  color: #94a3b8;
  font-size: 9px;
  letter-spacing: 0.06em;
}

.lca-side strong,
.lca-result strong {
  color: #cbd5e1;
  font: 700 13px "SFMono-Regular", Consolas, monospace;
  overflow-wrap: anywhere;
}

.lca-side.left.chosen {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.1);
}

.lca-side.right.chosen {
  border-color: #c084fc;
  background: rgba(192, 132, 252, 0.1);
}

.lca-decision {
  display: grid;
  place-items: center;
  color: #cbd5e1;
  font-size: 12px;
  text-align: center;
}

.lca-decision.equal {
  border-color: #10b981;
  color: #6ee7b7;
  background: rgba(16, 185, 129, 0.1);
}

.lca-decision.base {
  border-style: dashed;
}

.lca-decision.done,
.lca-result.ready {
  border-color: #10b981;
  background: rgba(16, 185, 129, 0.1);
}

.lca-result.ready strong {
  color: #6ee7b7;
}

.lca-progress {
  height: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(100, 116, 139, 0.25);
}

.lca-progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #10b981;
  transition: width 0.2s ease;
}

.lca-progress-label {
  margin-top: -6px;
  text-align: right;
}

.tree-annotation.lca-current { fill: #f59e0b; }
.tree-annotation.lca-returned { fill: #94a3b8; }
.tree-annotation.lca-left { fill: #38bdf8; }
.tree-annotation.lca-right { fill: #c084fc; }
.tree-annotation.lca-null { fill: #64748b; }
.tree-annotation.lca-deepest { fill: #f59e0b; }
.tree-annotation.lca-answer { fill: #10b981; }

[data-theme="light"] .lca-deepest-guide { color: #1e293b; }
[data-theme="light"] .lca-contract,
[data-theme="light"] .lca-side,
[data-theme="light"] .lca-decision,
[data-theme="light"] .lca-result,
[data-theme="light"] .lca-stack-node { background: rgba(241, 245, 249, 0.9); }
[data-theme="light"] .lca-contract strong,
[data-theme="light"] .lca-contract code { color: #0f172a; }
[data-theme="light"] .lca-side strong,
[data-theme="light"] .lca-result strong,
[data-theme="light"] .lca-decision { color: #334155; }
[data-theme="light"] .lca-decision.equal,
[data-theme="light"] .lca-result.ready strong { color: #047857; }
[data-theme="light"] .tree-annotation.lca-current,
[data-theme="light"] .tree-annotation.lca-deepest { fill: #b45309; }
[data-theme="light"] .tree-annotation.lca-returned { fill: #475569; }
[data-theme="light"] .tree-annotation.lca-left { fill: #0369a1; }
[data-theme="light"] .tree-annotation.lca-right { fill: #7e22ce; }
[data-theme="light"] .tree-annotation.lca-null { fill: #64748b; }
[data-theme="light"] .tree-annotation.lca-answer { fill: #047857; }

@media (max-width: 760px) {
  .lca-compare-row {
    grid-template-columns: 1fr 1fr;
  }

  .lca-decision,
  .lca-result {
    grid-column: 1 / -1;
  }
}

@media (max-width: 480px) {
  .lca-stack-row,
  .lca-compare-row {
    grid-template-columns: 1fr;
  }

  .lca-decision,
  .lca-result {
    grid-column: auto;
  }
}

/* ---- Same Tree (#100): compare corresponding nodes in two trees ---- */
.same-tree-viz {
  display: grid;
  gap: 14px;
  min-width: 0;
  color: #e2e8f0;
  letter-spacing: 0;
}

.same-tree-compare {
  display: grid;
  grid-template-columns: minmax(120px, auto) minmax(260px, 1fr) minmax(132px, auto);
  gap: 14px;
  align-items: center;
  padding: 0 4px 14px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}

.same-tree-path {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.same-tree-path small {
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
}

.same-tree-path code {
  color: #cbd5e1;
  overflow-wrap: anywhere;
}

.same-tree-pair {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-width: 0;
}

.same-tree-value {
  display: inline-flex;
  align-items: baseline;
  justify-content: center;
  gap: 9px;
  min-width: 98px;
  padding: 9px 12px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.48);
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
}

.same-tree-value small {
  color: #94a3b8;
  font-size: 12px;
  font-weight: 700;
}

.same-tree-value strong {
  color: #f8fafc;
  font-size: 19px;
}

.same-tree-relation {
  min-width: 22px;
  color: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 18px;
  font-weight: 700;
  text-align: center;
}

.same-tree-status {
  justify-self: end;
  padding: 7px 10px;
  border: 1px solid rgba(56, 189, 248, 0.3);
  border-radius: 999px;
  background: rgba(56, 189, 248, 0.1);
  color: #7dd3fc;
  font-size: 12px;
  font-weight: 700;
  text-align: center;
}

.same-tree-status.is-match {
  border-color: rgba(16, 185, 129, 0.35);
  background: rgba(16, 185, 129, 0.12);
  color: #6ee7b7;
}

.same-tree-status.is-mismatch {
  border-color: rgba(239, 68, 68, 0.35);
  background: rgba(239, 68, 68, 0.11);
  color: #fca5a5;
}

.same-tree-columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  min-width: 0;
}

.same-tree-column {
  min-width: 0;
  padding: 0 16px;
}

.same-tree-column + .same-tree-column {
  border-left: 1px solid rgba(148, 163, 184, 0.18);
}

.same-tree-column h4 {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 0 0 4px;
  color: #e2e8f0;
  font-size: 13px;
  letter-spacing: 0;
}

.same-tree-column h4 code {
  color: #f8fafc;
  font-size: 16px;
}

.same-tree-column h4 span {
  color: #64748b;
  font-size: 11px;
  font-weight: 600;
}

.same-tree-canvas {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 152px;
  overflow-x: auto;
}

.same-tree-canvas .tree-svg {
  max-width: 100%;
  height: auto;
}

.same-tree-empty {
  color: #64748b;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 28px;
}

.same-tree-legend {
  display: flex;
  justify-content: center;
  gap: 18px;
  flex-wrap: wrap;
  padding-top: 10px;
  border-top: 1px solid rgba(148, 163, 184, 0.18);
  color: #94a3b8;
  font-size: 11px;
}

.same-tree-legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.same-tree-legend i {
  width: 10px;
  height: 10px;
  border: 2px solid #64748b;
  border-radius: 50%;
}

.same-tree-legend i.current { border-color: #f59e0b; }
.same-tree-legend i.matched { border-color: #10b981; }

[data-theme="light"] .same-tree-viz { color: #1e293b; }
[data-theme="light"] .same-tree-compare,
[data-theme="light"] .same-tree-column + .same-tree-column,
[data-theme="light"] .same-tree-legend { border-color: #e2e8f0; }
[data-theme="light"] .same-tree-path code,
[data-theme="light"] .same-tree-column h4 { color: #334155; }
[data-theme="light"] .same-tree-value {
  background: #ffffff;
  border-color: #cbd5e1;
}
[data-theme="light"] .same-tree-value strong,
[data-theme="light"] .same-tree-column h4 code { color: #0f172a; }
[data-theme="light"] .same-tree-status.is-checking { color: #0369a1; }
[data-theme="light"] .same-tree-status.is-match { color: #047857; }
[data-theme="light"] .same-tree-status.is-mismatch { color: #b91c1c; }

@media (max-width: 768px) {
  .same-tree-compare {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .same-tree-path { text-align: center; }
  .same-tree-status { justify-self: center; }

  .same-tree-columns {
    grid-template-columns: 1fr;
  }

  .same-tree-column {
    padding: 8px 0;
  }

  .same-tree-column + .same-tree-column {
    padding-top: 14px;
    border-top: 1px solid rgba(148, 163, 184, 0.18);
    border-left: 0;
  }

  .same-tree-column h4 { justify-content: center; }
  .same-tree-canvas { min-height: 132px; }
}

/* ---- Sorted List to BST (#109): slow/fast split and recursive build ---- */
.sorted-list-bst-viz {
  display: grid;
  gap: 14px;
  min-width: 0;
  color: #e2e8f0;
  letter-spacing: 0;
}

.slb-call-stack {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}

.slb-call-stack > strong {
  color: #64748b;
  font-size: 10px;
  letter-spacing: 0;
}

.slb-call-stack > div {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  overflow-x: auto;
  padding: 2px;
}

.slb-frame {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  flex: 0 0 auto;
  padding: 5px 8px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.42);
  color: #94a3b8;
}

.slb-frame.active {
  border-color: rgba(56, 189, 248, 0.5);
  background: rgba(56, 189, 248, 0.1);
  color: #e0f2fe;
}

.slb-frame small {
  font-size: 10px;
  font-weight: 700;
}

.slb-frame code { color: inherit; }
.slb-stack-arrow { color: #64748b; }

.slb-status-row {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.slb-status-row.array-mode {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.slb-status {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 8px 10px;
  border-left: 3px solid #64748b;
  background: rgba(15, 23, 42, 0.36);
}

.slb-status code {
  color: #94a3b8;
  font-size: 10px;
}

.slb-status strong {
  min-width: 0;
  color: #f8fafc;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.slb-status.head { border-color: #38bdf8; }
.slb-status.prev { border-color: #a78bfa; }
.slb-status.slow { border-color: #34d399; }
.slb-status.fast { border-color: #f59e0b; }
.slb-status.array { border-color: #22d3ee; }
.slb-status.range { border-color: #818cf8; }
.slb-status.mid { border-color: #f59e0b; }

.slb-list-panel,
.slb-array-panel,
.slb-tree-panel {
  min-width: 0;
  padding-top: 2px;
}

.slb-array-panel,
.slb-tree-panel {
  border-top: 1px solid rgba(148, 163, 184, 0.18);
  padding-top: 12px;
}

.slb-section-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 6px;
}

.slb-section-title strong {
  color: #e2e8f0;
  font-size: 13px;
}

.slb-section-title span {
  color: #94a3b8;
  font-size: 11px;
  text-align: right;
}

.slb-section-title code { color: #7dd3fc; }

.slb-list-scroll {
  min-width: 0;
  overflow-x: auto;
  padding: 4px 2px 8px;
}

.slb-list-row {
  display: flex;
  align-items: flex-end;
  width: max-content;
  min-width: 100%;
  justify-content: center;
}

.slb-list-item {
  flex: 0 0 68px;
}

.slb-pointer-stack {
  display: flex;
  flex-wrap: wrap;
  align-content: flex-end;
  justify-content: center;
  gap: 2px;
  height: 42px;
  padding: 0 1px 4px;
}

.slb-pointer {
  padding: 2px 4px;
  border-radius: 4px;
  color: #0f172a;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 9px;
  font-weight: 800;
}

.slb-pointer.head { background: #38bdf8; }
.slb-pointer.prev { background: #a78bfa; }
.slb-pointer.slow { background: #34d399; }
.slb-pointer.fast { background: #f59e0b; }

.slb-node {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
  width: 68px;
  height: 56px;
  border: 1px solid rgba(56, 189, 248, 0.48);
  border-radius: 7px;
  background: rgba(56, 189, 248, 0.1);
  color: #f8fafc;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
}

.slb-node strong { font-size: 18px; }
.slb-node small { color: #94a3b8; font-size: 10px; }

.slb-node.outside {
  border-color: rgba(100, 116, 139, 0.2);
  background: rgba(100, 116, 139, 0.05);
  color: #64748b;
  opacity: 0.48;
}

.slb-node.picked {
  border-color: rgba(34, 197, 94, 0.5);
  background: rgba(34, 197, 94, 0.12);
}

.slb-node.copied {
  border-color: rgba(34, 211, 238, 0.5);
  background: rgba(34, 211, 238, 0.1);
}

.slb-node.pointed {
  box-shadow: 0 0 0 2px rgba(248, 250, 252, 0.12);
}

.slb-link {
  display: grid;
  place-items: center;
  align-content: center;
  flex: 0 0 34px;
  height: 56px;
  color: #94a3b8;
}

.slb-link strong {
  font-size: 20px;
  line-height: 1;
}

.slb-link small {
  color: #fb7185;
  font-size: 9px;
  font-weight: 700;
}

.slb-link.is-cut { color: #fb7185; }

.slb-array-scroll {
  min-width: 0;
  overflow-x: auto;
  padding: 18px 2px 8px;
}

.slb-array-row {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 70px;
  gap: 8px;
