  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.gasdep-dot {
  width: 24px; height: 24px;
  border-radius: 50%;
  border: 3px solid #64748b;
  background: #1e293b;
  box-sizing: border-box;
}
.gasdep-mlabel {
  display: flex;
  flex-direction: column;
  align-items: center;
  font-size: 11px;
  line-height: 1.3;
  white-space: nowrap;
}
.gasdep-mpos { color: #cbd5e1; font-weight: 600; }
.gasdep-mgas { color: #fbbf24; }
.gasdep-marker.state-start .gasdep-dot { border-color: #fbbf24; background: #422006; }
.gasdep-marker.state-collected .gasdep-dot { border-color: #22c55e; background: #052e16; }
.gasdep-marker.state-unreached .gasdep-dot { border-color: #ef4444; background: #450a0a; }
.gasdep-marker.state-before-start { opacity: .4; }
.gasdep-marker.state-pending .gasdep-dot { border-style: dashed; }
.gasdep-marker.is-current .gasdep-dot {
  border-color: #6366f1;
  box-shadow: 0 0 0 4px rgba(99,102,241,.35);
  transform: scale(1.15);
}
.gasdep-car {
  position: absolute;
  top: -6px;
  transform: translateX(-50%);
  font-size: 26px;
  transition: left .3s ease;
  z-index: 2;
}
.gasdep-scale {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  margin-top: 6px;
}
.gasdep-legend { display: flex; flex-wrap: wrap; gap: 12px; font-size: 12px; color: #94a3b8; }
.gasdep-legend span { display: inline-flex; align-items: center; gap: 5px; }
.gasdep-legend i { width: 14px; height: 14px; border-radius: 50%; display: inline-block; border: 3px solid #64748b; box-sizing: border-box; }
.gasdep-legend i.lg-start { border-color: #fbbf24; background: #422006; }
.gasdep-legend i.lg-collected { border-color: #22c55e; background: #052e16; }
.gasdep-legend i.lg-current { border-color: #6366f1; }
.gasdep-legend i.lg-unreached { border-color: #ef4444; background: #450a0a; }
.gasdep-legend i.lg-pending { border-style: dashed; }

[data-theme="light"] .gasdep-viz { color: #1e293b; }
[data-theme="light"] .gasdep-box { background: #f8fafc; border-color: #cbd5e1; }
[data-theme="light"] .gasdep-baseline { background: #cbd5e1; }
[data-theme="light"] .gasdep-dot { background: #f1f5f9; }
[data-theme="light"] .gasdep-mpos { color: #475569; }
[data-theme="light"] .gasdep-legend { color: #64748b; }

/* ---- Gas Station track (#134) ---- */
.gas-station-viz {
  display: grid;
  gap: 16px;
  min-width: 0;
  color: #e2e8f0;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  padding: 4px;
}
.gas-feasibility {
  display: grid;
  gap: 8px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid #334155;
  background: #0f172a;
}
.gas-feasibility.ok { border-color: #22c55e; }
.gas-feasibility.bad { border-color: #ef4444; }
.gas-feas-row { display: flex; align-items: center; gap: 10px; }
.gas-feas-label { min-width: 120px; font-size: 13px; }
.gas-feas-bar {
  flex: 1;
  height: 16px;
  background: #1e293b;
  border-radius: 8px;
  overflow: hidden;
}
.gas-feas-fill { height: 100%; border-radius: 8px; transition: width .3s ease; }
.gas-feas-fill.gas { background: linear-gradient(90deg, #34d399, #10b981); }
.gas-feas-fill.cost { background: linear-gradient(90deg, #fb923c, #f97316); }
.gas-feas-verdict { font-size: 13px; font-weight: 600; margin-top: 2px; }
.gas-feasibility.ok .gas-feas-verdict { color: #4ade80; }
.gas-feasibility.bad .gas-feas-verdict { color: #f87171; }

.gas-tank-gauge { display: flex; gap: 14px; flex-wrap: wrap; }
.gas-tank-box, .gas-start-box {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 16px;
  border-radius: 12px;
  border: 1px solid #334155;
  background: #0f172a;
  min-width: 140px;
}
.gas-tank-label, .gas-start-label { font-size: 12px; color: #94a3b8; }
.gas-tank-value, .gas-start-value { font-size: 24px; font-weight: 700; }
.gas-tank-box.pos .gas-tank-value { color: #4ade80; }
.gas-tank-box.neg { border-color: #ef4444; }
.gas-tank-box.neg .gas-tank-value { color: #f87171; }
.gas-start-value { color: #fbbf24; }

.gas-track {
  display: flex;
  align-items: stretch;
  gap: 4px;
  flex-wrap: wrap;
}
.gas-arrow { align-self: center; color: #64748b; font-size: 18px; }
.gas-station-card {
  display: grid;
  gap: 4px;
  padding: 8px 10px;
  border-radius: 10px;
  border: 2px solid #334155;
  background: #1e293b;
  min-width: 96px;
  transition: all .2s ease;
}
.gas-station-card.state-pending { opacity: .55; }
.gas-station-card.state-reached { border-color: #38bdf8; background: #0c2a3a; }
.gas-station-card.state-discarded { opacity: .5; border-color: #475569; background: #1a1a1a; }
.gas-station-card.state-discarded .gas-st-head { text-decoration: line-through; }
.gas-station-card.state-answer { border-color: #22c55e; background: #052e16; box-shadow: 0 0 0 3px rgba(34,197,94,.35); }
.gas-station-card.is-current { border-color: #6366f1; box-shadow: 0 0 0 3px rgba(99,102,241,.4); transform: translateY(-3px); }
.gas-station-card.is-start { border-color: #fbbf24; }
.gas-st-head { font-size: 12px; font-weight: 700; display: flex; flex-direction: column; gap: 2px; }
.gas-st-badge { font-size: 10px; color: #fbbf24; font-weight: 600; }
.gas-station-card.state-answer .gas-st-badge { color: #4ade80; }
.gas-st-row { display: flex; justify-content: space-between; font-size: 12px; color: #cbd5e1; }
.gas-st-net { font-size: 13px; font-weight: 700; text-align: center; border-radius: 6px; padding: 2px 0; }
.gas-st-net.pos { color: #4ade80; background: rgba(34,197,94,.12); }
.gas-st-net.neg { color: #f87171; background: rgba(239,68,68,.12); }
.gas-st-tank { font-size: 12px; text-align: center; color: #94a3b8; border-top: 1px dashed #334155; padding-top: 3px; }
.gas-st-tank.pos { color: #7dd3fc; }
.gas-st-tank.neg { color: #f87171; font-weight: 700; }

.gas-legend { display: flex; flex-wrap: wrap; gap: 12px; font-size: 12px; color: #94a3b8; }
.gas-legend span { display: inline-flex; align-items: center; gap: 5px; }
.gas-legend i { width: 14px; height: 14px; border-radius: 4px; display: inline-block; border: 2px solid transparent; }
.gas-legend i.lg-pending { background: #334155; opacity: .55; }
.gas-legend i.lg-reached { background: #0c2a3a; border-color: #38bdf8; }
.gas-legend i.lg-current { background: #1e293b; border-color: #6366f1; }
.gas-legend i.lg-start { background: #1e293b; border-color: #fbbf24; }
.gas-legend i.lg-discarded { background: #1a1a1a; border-color: #475569; }
.gas-legend i.lg-answer { background: #052e16; border-color: #22c55e; }

[data-theme="light"] .gas-station-viz { color: #1e293b; }
[data-theme="light"] .gas-feasibility,
[data-theme="light"] .gas-tank-box,
[data-theme="light"] .gas-start-box { background: #f8fafc; border-color: #cbd5e1; }
[data-theme="light"] .gas-station-card { background: #f1f5f9; border-color: #cbd5e1; }
[data-theme="light"] .gas-station-card.state-reached { background: #e0f2fe; }
[data-theme="light"] .gas-station-card.state-answer { background: #dcfce7; }
[data-theme="light"] .gas-feas-bar { background: #e2e8f0; }
[data-theme="light"] .gas-st-row { color: #475569; }
[data-theme="light"] .gas-legend { color: #64748b; }

/* ---- Real-time experience profit tracker (#9001) ---- */
.profit-tracker-viz {
  display: grid;
  gap: 14px;
  min-width: 0;
  color: #e2e8f0;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  letter-spacing: 0;
}

.profit-ops {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(92px, 1fr));
  gap: 6px;
}

.profit-op {
  position: relative;
  min-width: 0;
  min-height: 64px;
  padding: 9px 8px 8px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.48);
  color: #64748b;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.profit-op strong {
  font-size: 14px;
  color: #94a3b8;
}

.profit-op span:last-child {
  font-size: 10px;
}

.profit-op-index {
  position: absolute;
  top: 4px;
  left: 6px;
  font-size: 9px;
  color: #64748b;
}

.profit-op.done {
  border-color: rgba(16, 185, 129, 0.32);
  background: rgba(16, 185, 129, 0.07);
}

.profit-op.done strong {
  color: #6ee7b7;
}

.profit-op.active {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.12);
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.12);
}

.profit-op.active strong,
.profit-op.active span:last-child {
  color: #fbbf24;
}

.profit-action {
  min-height: 48px;
  padding: 10px 12px;
  border-left: 3px solid #818cf8;
  background: rgba(99, 102, 241, 0.09);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 8px;
  text-align: center;
  font-size: 12px;
}

.profit-action strong {
  color: #c7d2fe;
}

.profit-action em {
  color: #94a3b8;
  font-size: 10px;
  font-style: normal;
}

.profit-action .is-current {
  color: #6ee7b7;
}

.profit-action .is-stale {
  color: #fda4af;
}

.profit-arrow {
  color: #818cf8;
  font-weight: 700;
}

.profit-state-grid {
  display: grid;
  grid-template-columns: minmax(150px, 0.72fr) minmax(0, 1.65fr);
  gap: 14px;
}

.profit-state-panel {
  min-width: 0;
  padding-top: 8px;
  border-top: 1px solid rgba(148, 163, 184, 0.2);
}

.profit-state-panel h4 {
  margin: 0 0 8px;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

.profit-total-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 7px 8px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.12);
  font-size: 12px;
}

.profit-total-row strong {
  color: #6ee7b7;
  font-size: 14px;
}

.profit-heap-list {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 8px;
}

.profit-heap-entry {
  flex: 1 1 132px;
  min-width: 0;
  max-width: 190px;
  padding: 8px 9px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.42);
}

.profit-heap-entry.current {
  border-color: rgba(16, 185, 129, 0.45);
}

.profit-heap-entry.stale {
  border-color: rgba(244, 63, 94, 0.5);
  background: rgba(244, 63, 94, 0.07);
}

.profit-heap-entry.root {
  box-shadow: inset 0 3px 0 #f59e0b;
}

.profit-heap-entry.focused {
  outline: 2px solid rgba(245, 158, 11, 0.6);
  outline-offset: 2px;
}

.profit-heap-top {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  color: #94a3b8;
  font-size: 9px;
}

.profit-heap-entry.current .profit-heap-top strong {
  color: #6ee7b7;
}

.profit-heap-entry.stale .profit-heap-top strong {
  color: #fda4af;
}

.profit-heap-name {
  margin-top: 4px;
  color: #f8fafc;
  font-size: 13px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.profit-heap-values {
  display: grid;
  gap: 1px;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 9px;
  overflow-wrap: anywhere;
}

.profit-result-row,
.profit-legend {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
}

.profit-result-row {
  padding-top: 9px;
  border-top: 1px solid rgba(148, 163, 184, 0.2);
  font-size: 11px;
}

.profit-result-item {
  padding: 4px 7px;
  border-radius: 5px;
  background: rgba(99, 102, 241, 0.16);
  color: #c7d2fe;
}

.profit-legend {
  color: #94a3b8;
  font-size: 9px;
}

.profit-legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.profit-legend i {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: #64748b;
}

.profit-legend i.current { background: #10b981; }
.profit-legend i.stale { background: #f43f5e; }
.profit-legend i.root { background: #f59e0b; }

.profit-empty {
  color: #64748b;
  font-size: 11px;
  padding: 8px 0;
}

[data-theme="light"] .profit-tracker-viz {
  color: #1e293b;
}

[data-theme="light"] .profit-op,
[data-theme="light"] .profit-heap-entry {
  background: #ffffff;
}

[data-theme="light"] .profit-op.done {
  background: #ecfdf5;
}

[data-theme="light"] .profit-op.active {
  background: #fffbeb;
}

[data-theme="light"] .profit-op.done strong,
[data-theme="light"] .profit-total-row strong,
[data-theme="light"] .profit-heap-entry.current .profit-heap-top strong {
  color: #047857;
}

[data-theme="light"] .profit-op.active strong,
[data-theme="light"] .profit-op.active span:last-child {
  color: #b45309;
}

[data-theme="light"] .profit-action {
  background: #eef2ff;
}

[data-theme="light"] .profit-action strong,
[data-theme="light"] .profit-result-item {
  color: #4338ca;
}

[data-theme="light"] .profit-action .is-current { color: #047857; }
[data-theme="light"] .profit-action .is-stale,
[data-theme="light"] .profit-heap-entry.stale .profit-heap-top strong { color: #be123c; }

[data-theme="light"] .profit-heap-entry.stale {
  background: #fff1f2;
}

[data-theme="light"] .profit-heap-name {
  color: #0f172a;
}

[data-theme="light"] .profit-result-item {
  background: #eef2ff;
}

@media (max-width: 760px) {
  .profit-ops {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .profit-state-grid {
    grid-template-columns: 1fr;
  }

  .profit-heap-entry {
    max-width: none;
  }
}

/* ---- Meeting-room allocation timeline (#253) ---- */
.rooms-timeline-viz {
  color: #e2e8f0;
  overflow-x: auto;
}

.rooms-sorted-row,
.rooms-heap-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
