/* ---- Meeting interval timeline (#252) ---- */
.meeting-timeline-viz {
  color: #e2e8f0;
  overflow-x: auto;
}

.meeting-timeline-status {
  color: #94a3b8;
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.meeting-timeline-svg {
  display: block;
  width: 100%;
  min-width: 620px;
  height: auto;
}

.meeting-timeline-grid {
  stroke: rgba(148, 163, 184, 0.18);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.meeting-timeline-axis {
  stroke: #64748b;
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.meeting-timeline-tick,
.meeting-row-label,
.meeting-role-label,
.meeting-overlap-label {
  fill: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 12px;
  font-weight: 600;
}

.meeting-interval rect {
  fill: rgba(99, 102, 241, 0.13);
  stroke: #64748b;
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
  transition: fill 0.2s ease, stroke 0.2s ease;
}

.meeting-interval.processed rect {
  fill: rgba(16, 185, 129, 0.17);
  stroke: #10b981;
}

.meeting-interval.previous rect {
  fill: rgba(245, 158, 11, 0.24);
  stroke: #f59e0b;
  stroke-width: 2.5;
}

.meeting-interval.current rect,
.meeting-interval.active rect {
