}

.shift-track-cell.old-index.new-index {
  box-shadow: inset 0 0 0 2px #f97316, inset 0 0 0 4px #14b8a6;
}

.shift-array-lanes {
  display: grid;
  gap: 8px;
  margin-top: 18px;
  min-width: max-content;
}

.shift-array-lane {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.shift-array-name {
  width: 62px;
  color: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 11px;
  text-align: right;
}

.shift-array-values {
  display: flex;
  gap: 3px;
}

.shift-array-cell {
  width: 36px;
  height: 42px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(148, 163, 184, 0.2);
  color: #64748b;
  background: rgba(15, 23, 42, 0.35);
}

.shift-array-cell span {
  color: #64748b;
  font-size: 9px;
}

.shift-array-cell.filled {
  color: #cbd5e1;
}

.shift-array-cell.source-index {
  color: #fed7aa;
  background: rgba(249, 115, 22, 0.18);
  border: 2px solid #f97316;
}

.shift-array-cell.target-index {
  color: #ccfbf1;
  background: rgba(20, 184, 166, 0.2);
  border: 2px solid #14b8a6;
}

.shift-legend {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 14px;
  color: #94a3b8;
  font-size: 11px;
}

.shift-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.shift-legend i {
  width: 10px;
  height: 10px;
  border-radius: 2px;
}

.source-swatch { background: #f97316; }
.target-swatch { background: #14b8a6; }
.placed-swatch { background: #22c55e; }

.shift-empty {
  min-width: 180px;
  padding: 24px;
  color: #94a3b8;
  text-align: center;
}

[data-theme="light"] .shift-grid-viz {
  border-color: #dbe3ef;
  background: #f8fafc;
}

[data-theme="light"] .shift-phase,
[data-theme="light"] .shift-cell,
[data-theme="light"] .shift-formula strong {
  color: #1e293b;
}

[data-theme="light"] .shift-formula span,
[data-theme="light"] .shift-cell,
[data-theme="light"] .shift-track-cell,
[data-theme="light"] .shift-array-cell {
  background: #ffffff;
}

[data-theme="light"] .shift-cell {
  border-color: #cbd5e1;
}

[data-theme="light"] .shift-cell.source-active,
[data-theme="light"] .shift-track-cell.old-index,
[data-theme="light"] .shift-array-cell.source-index {
  color: #9a3412;
  background: #ffedd5;
}

[data-theme="light"] .shift-cell.target-active,
[data-theme="light"] .shift-array-cell.target-index {
  color: #115e59;
  background: #ccfbf1;
}

[data-theme="light"] .shift-cell.placed:not(.target-active) {
  color: #166534;
  background: #dcfce7;
}

@media (max-width: 640px) {
  .shift-grid-viz {
    min-height: 0;
    padding: 10px;
  }

  .shift-matrices {
    align-items: center;
    flex-direction: row;
    gap: 6px;
  }

  .shift-arrow {
    font-size: 18px;
    text-align: center;
  }

  .shift-matrix {
    grid-template-columns: repeat(var(--shift-cols), 37px);
    gap: 3px;
    justify-content: center;
  }

  .shift-cell {
    width: 37px;
    height: 44px;
  }

  .shift-cell strong {
    font-size: 14px;
  }

  .shift-coord {
    font-size: 8px;
  }

  .shift-track {
    margin-top: 12px;
  }

  .shift-track-cell {
    width: 27px;
    height: 36px;
  }

  .shift-array-lanes {
    margin-top: 12px;
  }

  .shift-array-name {
    width: 42px;
    font-size: 10px;
  }

  .shift-array-lane {
    gap: 4px;
  }

  .shift-array-cell {
    width: 20px;
    height: 36px;
  }

  .shift-array-cell strong {
    font-size: 10px;
  }
}

/* ---- Difficulty badges ---- */
.diff {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  text-transform: capitalize;
  letter-spacing: 0.02em;
}

.diff-easy {
  background: rgba(16, 185, 129, 0.12);
  color: #6ee7b7;
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.diff-medium {
  background: rgba(245, 158, 11, 0.12);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.diff-hard {
  background: rgba(239, 68, 68, 0.12);
  color: #fca5a5;
  border: 1px solid rgba(239, 68, 68, 0.3);
}

/* ---- Python syntax highlighting ---- */
.py-kw {
  color: #c084fc;
  font-weight: 600;
}

.py-builtin {
  color: #67e8f9;
}

.py-fn {
  color: #93c5fd;
}

.py-cls {
  color: #fcd34d;
}

.py-str {
  color: #86efac;
}

.py-comment {
  color: #64748b;
  font-style: italic;
}

.py-num {
  color: #fdba74;
}

/* ---- Catalog toggle ---- */
.cat-toggle {
  width: 26px;
  height: 26px;
  padding: 0;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.06);
  color: #e2e8f0;
  font-size: 16px;
  font-weight: 700;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: none;
  transition: all 0.15s;
}

.cat-toggle:hover {
  background: #6366f1;
  color: white;
  border-color: #6366f1;
  box-shadow: 0 2px 8px rgba(99, 102, 241, 0.3);
}

.cat-items.collapsed {
  display: none;
}


/* ---- Header actions row ---- */
.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.theme-toggle {
  width: 38px;
  height: 38px;
  padding: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #e2e8f0;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s;
  box-shadow: none;
}

.theme-toggle:hover {
  background: rgba(99, 102, 241, 0.15);
  border-color: rgba(99, 102, 241, 0.4);
  color: #a5b4fc;
  transform: none;
  box-shadow: 0 0 12px rgba(99, 102, 241, 0.2);
}

.theme-auto {
  min-width: 54px;
  height: 38px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 800;
  font-family: inherit;
  cursor: pointer;
  box-shadow: none;
  transition: all 0.2s;
}

.theme-auto:hover,
.theme-auto.active {
  background: rgba(99, 102, 241, 0.15);
  border-color: rgba(99, 102, 241, 0.48);
  color: #c7d2fe;
}

.theme-auto.active {
  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.35);
}

