/* ---- Graph (directed weighted) ---- */
.graph-svg {
  display: block;
  margin: 0 auto;
}

.graph-caption {
  color: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 12px;
  font-weight: 700;
  margin: 0 0 10px;
  text-align: center;
}

.graph-linear {
  max-width: 100%;
}

.graph-flow {
  max-width: 100%;
  height: auto;
}

.graph-edge {
  fill: none;
  stroke: #475569;
  stroke-width: 2;
  transition: stroke 0.25s;
}

.graph-edge.hl {
  stroke: #f59e0b;
  stroke-width: 3;
}

.graph-edge.dim,
.graph-weight.dim,
.graph-weight-bg.dim {
  opacity: 0.24;
}

.graph-weight-bg {
  fill: #151321;
  stroke: #334155;
  stroke-width: 1;
}

.graph-weight-bg.hl {
  fill: #2a2114;
  stroke: #f59e0b;
}

[data-theme="light"] .graph-weight-bg {
  fill: #ffffff;
  stroke: #cbd5e1;
}

[data-theme="light"] .graph-weight-bg.hl {
  fill: #fffbeb;
  stroke: #d97706;
}

.graph-edge.prev {
  stroke: #38bdf8;
}

.graph-edge.prev.hl {
  stroke: #f59e0b;
}

/* Committed MST / kept edges (green), rejected / removable edges (red dashed),
   and pseudo-critical edges (purple). Shared by #1135, #1489, #1579, #1627. */
.graph-edge.accept {
  stroke: #10b981;
  stroke-width: 3;
}

.graph-edge.reject {
  stroke: #ef4444;
  stroke-dasharray: 5 4;
  opacity: 0.7;
}

.graph-edge.pseudo {
  stroke: #a855f7;
  stroke-width: 3;
}

.graph-edge.critical {
  stroke: #ef4444;
  stroke-width: 3.5;
}

.graph-weight.accept {
  fill: #6ee7b7;
}

.graph-weight.reject {
  fill: #fca5a5;
}

.graph-weight.pseudo {
  fill: #d8b4fe;
}

.graph-weight.critical {
  fill: #fca5a5;
}

.graph-weight {
  fill: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 12px;
  font-weight: 700;
}

.graph-weight.hl {
  fill: #fbbf24;
}

.graph-weight.prev {
  fill: #7dd3fc;
}

.graph-weight.prev.hl {
  fill: #fbbf24;
}

.graph-column-divider {
  stroke: #334155;
  stroke-width: 1;
  stroke-dasharray: 4 4;
}

.graph-column-label {
  fill: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 12px;
  font-weight: 700;
}

[data-theme="light"] .graph-column-divider {
  stroke: #cbd5e1;
}

[data-theme="light"] .graph-column-label {
  fill: #64748b;
}

.graph-node circle {
  fill: rgba(30, 20, 50, 0.8);
  stroke: #64748b;
  stroke-width: 2.5;
  transition: stroke 0.25s, fill 0.25s;
}

.graph-node text {
  fill: #e2e8f0;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 15px;
  font-weight: 700;
}

.graph-node.visited circle {
  fill: rgba(16, 185, 129, 0.15);
  stroke: #10b981;
}

.graph-node.visited text {
  fill: #6ee7b7;
}

.graph-node.restricted circle {
  fill: rgba(239, 68, 68, 0.18);
