}

.graph-node.hl circle {
  fill: rgba(245, 158, 11, 0.15);
  stroke: #f59e0b;
  stroke-width: 3;
}

.graph-node.hl text {
  fill: #fbbf24;
}

.graph-dist {
  fill: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 11px;
  font-weight: 600;
}

.graph-dist.hl {
  fill: #fbbf24;
}

