/* ---- 486: Predict the Winner ---- */
.predict-winner-viz {
  display: grid;
  gap: 14px;
  width: 100%;
  min-width: 0;
}

.predict-winner-phases {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
}

.predict-winner-phases span {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-width: 0;
  padding: 8px 6px;
  color: #64748b;
  text-align: center;
}

.predict-winner-phases span.is-active {
  border-bottom: 3px solid #f59e0b;
  color: #e2e8f0;
}

.predict-winner-phases span.is-done {
  color: #6ee7b7;
}

.predict-winner-phases b {
  min-width: 0;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.predict-winner-array {
  display: flex;
  justify-content: center;
  gap: 8px;
  min-width: 0;
  padding: 4px 0 2px;
  overflow-x: auto;
}

.predict-winner-number {
  display: grid;
  grid-template-rows: 20px 32px 18px;
  align-items: center;
  flex: 0 0 76px;
  min-width: 0;
  min-height: 76px;
  padding: 5px 7px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.28);
  text-align: center;
}

.predict-winner-number.is-outside {
  opacity: 0.28;
}

.predict-winner-number.is-left {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.1);
}

.predict-winner-number.is-right {
  border-color: #a78bfa;
  background: rgba(167, 139, 250, 0.1);
}

.predict-winner-number.is-only {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.1);
}

.predict-winner-pointers {
  display: flex;
  justify-content: center;
  gap: 3px;
  min-width: 0;
}

.predict-winner-pointers span {
  color: #fbbf24;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 9px;
  font-weight: 700;
  white-space: nowrap;
}

.predict-winner-number strong {
  color: #f8fafc;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 21px;
}

.predict-winner-number small {
  color: #94a3b8;
  font-size: 10px;
}

.predict-winner-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  gap: 18px;
  align-items: stretch;
  min-width: 0;
}

.predict-winner-table-block {
  min-width: 0;
  padding-right: 18px;
  border-right: 1px solid rgba(148, 163, 184, 0.2);
}

.predict-winner-choice-block {
  display: grid;
  align-content: start;
  gap: 9px;
  min-width: 0;
}

.predict-winner-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
  margin-bottom: 8px;
  color: #94a3b8;
}

.predict-winner-section-head strong {
  color: #e2e8f0;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 13px;
}

.predict-winner-section-head span {
  min-width: 0;
  font-size: 11px;
  text-align: right;
  overflow-wrap: anywhere;
}

.predict-winner-table-scroll {
  max-width: 100%;
  overflow-x: auto;
}

.predict-winner-dp-grid {
  display: grid;
  grid-template-columns: 54px repeat(var(--predict-winner-size), minmax(50px, 1fr));
  width: max-content;
  min-width: 100%;
  gap: 4px;
}

.predict-winner-dp-cell {
  display: grid;
  grid-template-rows: 16px 24px;
  align-items: center;
  justify-items: center;
  min-width: 50px;
  min-height: 48px;
  padding: 3px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 5px;
  background: rgba(15, 23, 42, 0.24);
}

.predict-winner-dp-cell small {
  color: #64748b;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 8px;
}

.predict-winner-dp-cell strong {
  color: #cbd5e1;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 15px;
}

.predict-winner-dp-cell.is-header,
.predict-winner-dp-cell.is-corner {
  border-color: transparent;
  background: transparent;
}

.predict-winner-dp-cell.is-header strong {
  color: #94a3b8;
  font-size: 12px;
}

.predict-winner-dp-cell.is-corner {
  color: #64748b;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 10px;
}

.predict-winner-dp-cell.is-unused {
  border-color: transparent;
  background: rgba(15, 23, 42, 0.08);
}

.predict-winner-dp-cell.is-filled {
  background: rgba(99, 102, 241, 0.1);
