[data-theme="light"] .predict-winner-dp-cell.is-filled { background: #eef2ff; }
[data-theme="light"] .predict-winner-dp-cell.is-left-dependency { background: #ecfeff; border-color: #0891b2; }
[data-theme="light"] .predict-winner-dp-cell.is-right-dependency { background: #f5f3ff; border-color: #8b5cf6; }
[data-theme="light"] .predict-winner-dp-cell.is-active { background: #fffbeb; border-color: #d97706; }
[data-theme="light"] .predict-winner-dp-cell strong,
[data-theme="light"] .predict-winner-choice code,
[data-theme="light"] .predict-winner-rule code { color: #334155; }
