/* ---- 1140: Stone Game II ---- */
.stone-game-ii-viz {
  display: grid;
  gap: 12px;
  width: 100%;
  min-width: 0;
}

.sg2-phases {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
}

.sg2-phases span {
  min-width: 0;
  min-height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 6px 5px;
