  place-items: center;
  align-content: center;
  gap: 3px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.3);
  text-align: center;
}

.sg2-state-strip small {
  color: #94a3b8;
  font-size: 8px;
  font-weight: 800;
}

.sg2-state-strip strong {
  max-width: 100%;
  color: #e2e8f0;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.sg2-piles-section,
.sg2-suffix-section,
.sg2-options-section,
.sg2-table-section {
  min-width: 0;
}

.sg2-piles-section > header,
.sg2-suffix-section > header,
.sg2-options-section > header,
.sg2-table-section > header {
