  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
  color: #94a3b8;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 9px;
}

.sg2-piles-section > header strong,
.sg2-suffix-section > header strong,
.sg2-options-section > header strong,
.sg2-table-section > header strong {
