  font-size: 10px;
}

.sg2-piles-section > header span,
.sg2-suffix-section > header span,
.sg2-options-section > header span,
.sg2-table-section > header span {
  min-width: 0;
  text-align: right;
  overflow-wrap: anywhere;
}

.sg2-piles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(58px, 1fr));
  gap: 6px;
  min-width: 0;
  padding-top: 18px;
}

.sg2-pile {
  position: relative;
  min-width: 0;
  min-height: 82px;
  padding: 7px 5px 5px;
  display: grid;
  place-items: center;
  align-content: end;
  gap: 4px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.3);
  transition: opacity 0.15s ease, border-color 0.15s ease, background-color 0.15s ease;
}

.sg2-pile-bar {
  width: min(38px, 76%);
  height: var(--sg2-pile-height, 30px);
  min-height: 18px;
  display: grid;
  place-items: center;
  align-self: end;
  border: 1px solid rgba(148, 163, 184, 0.38);
  border-radius: 4px 4px 2px 2px;
  background: rgba(100, 116, 139, 0.3);
}

.sg2-pile-bar strong {
  color: #f8fafc;
  font-size: 14px;
}

.sg2-pile > small {
  color: #64748b;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 9px;
}

.sg2-pile.is-consumed {
