}

.rectangle-area-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
  margin-bottom: 8px;
}

.rectangle-area-section-head strong {
  color: #e2e8f0;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 12px;
}

.rectangle-area-section-head span {
  min-width: 0;
  color: #94a3b8;
  font-size: 10px;
  text-align: right;
  overflow-wrap: anywhere;
}

.rectangle-area-plot {
  display: block;
  width: 100%;
  height: auto;
  max-height: 390px;
  overflow: visible;
}

.rectangle-area-grid-line {
