}

.rectangle-area-scan-point {
  fill: #cffafe;
  stroke: #0891b2;
  stroke-width: 2;
}

.rectangle-area-state {
  display: grid;
  align-content: start;
  gap: 15px;
  min-width: 0;
}

.rectangle-area-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}

.rectangle-area-metrics > span {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 5px;
  min-width: 0;
  min-height: 40px;
  padding: 6px 8px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 5px;
  background: rgba(15, 23, 42, 0.25);
}

.rectangle-area-metrics small {
  min-width: 0;
