}

.rectangle-area-metrics strong {
  color: #e2e8f0;
  font-family: "SFMono-Regular", Consolas, Menlo, monospace;
  font-size: 15px;
}

.rectangle-area-metrics .is-total {
  border-color: rgba(16, 185, 129, 0.6);
