}

.rectangle-area-metrics .is-total strong {
  color: #6ee7b7;
}

.rectangle-area-state-section {
  min-width: 0;
  padding-top: 11px;
  border-top: 1px solid rgba(148, 163, 184, 0.18);
}

.rectangle-area-active-list {
  display: grid;
  gap: 5px;
}

.rectangle-area-interval {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 6px 8px;
  border-left: 3px solid #38bdf8;
  background: rgba(56, 189, 248, 0.07);
}

.rectangle-area-interval:nth-child(2n) {
