.classroom-grid .bfs-cell.litter { background: #164e63; color: #a5f3fc; }
.classroom-grid .bfs-cell.reset { background: #14532d; color: #bbf7d0; }
.classroom-grid .bfs-cell.wall { background: #334155; color: #cbd5e1; }
.classroom-grid .bfs-cell.collected { box-shadow: inset 0 0 0 3px #22c55e; }
.classroom-grid .bfs-cell.visited:not(.current):not(.path) { filter: saturate(0.75); opacity: 0.78; }
.classroom-grid .bfs-cell.queued:not(.current):not(.path) { box-shadow: inset 0 0 0 3px #fbbf24; }
.classroom-grid .bfs-cell.path { background: #22c55e; color: #052e16; transform: translateY(-2px); }
.classroom-grid .bfs-cell.current { background: #f59e0b; color: #111827; transform: translateY(-2px); }
.classroom-grid .bfs-cell.route:not(.current) { background: #0d9488; color: #ecfeff; box-shadow: inset 0 0 0 3px #5eead4; }

.classroom-guide {
  width: min(100%, 920px);
  margin: 0 auto 18px;
  color: #e2e8f0;
  text-align: left;
}

.classroom-phases {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border: 1px solid #334155;
  border-radius: 7px;
  overflow: hidden;
}

.classroom-phases span {
  padding: 9px 8px;
  border-right: 1px solid #334155;
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
  text-align: center;
}

.classroom-phases span:last-child { border-right: 0; }
.classroom-phases span.active { background: #312e81; color: #e0e7ff; }

.classroom-rule {
