  border-bottom: 1px solid #334155;
}

.classroom-rule strong { color: #a5b4fc; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; }
.classroom-rule span { color: #94a3b8; font-size: 11px; }

.classroom-guide-main {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: 18px;
  padding: 14px 0;
}

.classroom-guide section > header,
.classroom-litter > header,
.classroom-queue > header,
.classroom-route > header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.classroom-guide section > header strong { color: #cbd5e1; font-size: 10px; letter-spacing: 0; }
.classroom-guide section > header span { color: #64748b; font-size: 9px; text-align: right; }

.classroom-state-tuple {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  min-height: 68px;
  border: 1px solid #334155;
