.classroom-state-tuple > span:last-child { border-right: 0; }
.classroom-state-tuple small { color: #64748b; font-size: 8px; font-weight: 800; }
.classroom-state-tuple strong { margin-top: 4px; color: #f8fafc; font-size: 15px; }
.classroom-state-tuple em { margin-top: 3px; color: #cbd5e1; font-size: 8px; font-style: normal; }

.classroom-battery {
  position: relative;
  width: 100%;
