  top: 2px;
  right: -4px;
  width: 3px;
  height: 5px;
  border-radius: 0 2px 2px 0;
  background: #64748b;
  content: "";
}

.classroom-battery i { display: block; width: var(--energy-level); height: 100%; background: #22c55e; }
.classroom-state-empty { display: grid; min-height: 68px; place-items: center; border: 1px dashed #334155; color: #64748b; font-size: 11px; }

.classroom-candidate {
  display: grid;
  grid-template-columns: minmax(100px, 1.1fr) minmax(0, 0.8fr) minmax(0, 1.2fr);
  align-items: center;
