.classroom-candidate > div { min-width: 0; padding: 8px; }
.classroom-candidate small { display: block; color: #64748b; font-size: 8px; font-weight: 800; }
.classroom-candidate strong { display: block; margin-top: 4px; color: #f8fafc; font-size: 12px; overflow-wrap: anywhere; }
.classroom-candidate.idle { display: grid; place-items: center; border-left-width: 1px; border-style: dashed; color: #64748b; font-size: 11px; }

.classroom-transition {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  color: #cbd5e1;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 9px;
}

.classroom-transition b { color: #8b5cf6; }

.classroom-decision {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-left: 4px solid #8b5cf6;
  background: rgba(139, 92, 246, 0.1);
}

.classroom-decision strong { min-width: 92px; color: #c4b5fd; font-size: 9px; }
.classroom-decision span { color: #ddd6fe; font-size: 11px; }
.classroom-decision.accepted,
.classroom-decision.success { border-left-color: #22c55e; background: rgba(34, 197, 94, 0.1); }
.classroom-decision.accepted strong,
.classroom-decision.success strong,
.classroom-decision.accepted span,
.classroom-decision.success span { color: #bbf7d0; }
.classroom-decision.rejected { border-left-color: #ef4444; background: rgba(239, 68, 68, 0.1); }
.classroom-decision.rejected strong,
.classroom-decision.rejected span { color: #fecaca; }
.classroom-decision.dominated { border-left-color: #f59e0b; background: rgba(245, 158, 11, 0.1); }
.classroom-decision.dominated strong,
.classroom-decision.dominated span { color: #fde68a; }

.classroom-litter,
.classroom-queue,
.classroom-route { padding: 13px 0 0; border-top: 1px solid #334155; }
.classroom-litter > div { display: flex; flex-wrap: wrap; gap: 8px; }
.classroom-litter > div > span { display: inline-grid; grid-template-columns: 18px auto; align-items: center; column-gap: 6px; padding: 6px 9px; border: 1px solid #475569; border-radius: 6px; }
.classroom-litter > div > span i { grid-row: 1 / span 2; display: grid; width: 18px; height: 18px; place-items: center; border: 1px solid #64748b; border-radius: 3px; color: #052e16; font-size: 11px; font-style: normal; }
.classroom-litter > div > span strong { color: #a5f3fc; font-size: 11px; }
