.classroom-litter > div > span.done i { border-color: #22c55e; background: #22c55e; }

.classroom-queue > div { display: flex; gap: 7px; overflow-x: auto; padding-bottom: 3px; }
.classroom-queue > div > span { flex: 0 0 auto; min-width: 128px; padding: 7px 9px; border: 1px solid #334155; border-radius: 6px; }
.classroom-queue > div > span b { display: block; color: #fbbf24; font-size: 7px; }
.classroom-queue > div > span strong { display: block; margin: 2px 0; color: #f8fafc; font-size: 11px; }
.classroom-queue > div > span small { color: #94a3b8; font-size: 8px; }
.classroom-queue em,
.classroom-litter em { color: #64748b; font-size: 10px; font-style: normal; }

.classroom-route > div { display: flex; align-items: center; gap: 6px; overflow-x: auto; padding: 2px 0 5px; }
.classroom-route > div > span { flex: 0 0 auto; padding: 6px 8px; border: 1px solid #14b8a6; border-radius: 6px; background: rgba(20, 184, 166, 0.1); }
.classroom-route > div > span small { display: block; color: #5eead4; font-size: 7px; }
.classroom-route > div > span strong { color: #ccfbf1; font-size: 10px; }
.classroom-route > div > b { color: #5eead4; font-size: 11px; }

@media (max-width: 760px) {
  .classroom-phases { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .classroom-phases span:nth-child(2) { border-right: 0; }
  .classroom-phases span:nth-child(-n + 2) { border-bottom: 1px solid #334155; }
  .classroom-rule { align-items: flex-start; flex-direction: column; gap: 4px; }
