  font-size: 10px;
  overflow-wrap: anywhere;
}

.lrk-edge-action small,
.lrk-degree-action small,
.lrk-seed-action small {
  color: #7dd3fc;
  font-size: 8px;
  font-weight: 800;
}

.lrk-degree-action { border-left-color: #10b981; background: rgba(16, 185, 129, 0.07); }
.lrk-degree-action code { color: #6ee7b7; font-size: 17px; font-weight: 850; }
.lrk-seed-action.ready { border-left-color: #10b981; background: rgba(16, 185, 129, 0.07); }
.lrk-seed-action.locked { border-left-color: #ef4444; background: rgba(239, 68, 68, 0.06); }
.lrk-seed-action code { color: #c4b5fd; font-size: 12px; }

.lrk-compare {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: stretch;
  gap: 6px;
}

.lrk-compare > span {
  min-width: 0;
  min-height: 78px;
  padding: 7px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
  border: 1px solid #475569;
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.25);
  text-align: center;
}

.lrk-compare > span.candidate {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.07);
}

.lrk-compare span small { color: #94a3b8; font-size: 7px; }
.lrk-compare span strong { color: #f8fafc; font-size: 17px; }
.lrk-compare span b { color: #cbd5e1; font-size: 10px; }

.lrk-compare > div {
  min-width: 56px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 4px;
}

.lrk-compare code { color: #fbbf24; font-size: 13px; font-weight: 850; }
.lrk-compare > div > strong { padding: 3px 6px; border-radius: 4px; font-size: 8px; }
.lrk-compare > div > strong.update { background: rgba(16, 185, 129, 0.14); color: #6ee7b7; }
.lrk-compare > div > strong.keep { background: rgba(148, 163, 184, 0.12); color: #94a3b8; }

.lrk-indegree {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.lrk-indegree > div {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(58px, 1fr));
  gap: 5px;
}

.lrk-indegree > div > span {
  min-width: 0;
  min-height: 52px;
  padding: 4px;
  display: grid;
  place-items: center;
  align-content: center;
  border: 1px solid #475569;
  border-radius: 5px;
  background: rgba(15, 23, 42, 0.26);
}

.lrk-indegree small { color: #64748b; font-size: 8px; }
.lrk-indegree strong { color: #f8fafc; font-size: 15px; }
.lrk-indegree em { color: #94a3b8; font-size: 7px; font-style: normal; }
.lrk-indegree span.source { border-color: #f59e0b; }
.lrk-indegree span.target { border-color: #c084fc; }
.lrk-indegree span.ready { border-color: #38bdf8; background: rgba(56, 189, 248, 0.07); }
.lrk-indegree span.queued { border-color: #a78bfa; background: rgba(139, 92, 246, 0.08); }
.lrk-indegree span.processed { border-color: #10b981; background: rgba(16, 185, 129, 0.07); }

.lrk-topo {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}

.lrk-topo > strong {
  flex: 0 0 auto;
  color: #c4b5fd;
  font-size: 9px;
}

.lrk-topo > div {
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
}

.lrk-topo > div > span {
  min-width: 43px;
  min-height: 35px;
  padding: 3px 5px;
  display: grid;
  place-items: center;
  border: 1px solid #10b981;
  border-radius: 5px;
  background: rgba(16, 185, 129, 0.07);
}

.lrk-topo small { color: #64748b; font-size: 7px; }
.lrk-topo strong { color: #6ee7b7; font-size: 11px; }
.lrk-topo b,
.lrk-topo em { color: #64748b; font-size: 9px; font-style: normal; }

.lrk-answer {
  min-width: 0;
  padding-top: 8px;
  display: grid;
  gap: 6px;
  border-top: 1px solid #334155;
}

.lrk-answer > div {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(84px, 1fr));
  gap: 5px;
}

.lrk-answer > div > span {
  min-width: 0;
  min-height: 54px;
  padding: 5px 6px;
  display: grid;
  place-items: center;
  align-content: center;
  border: 1px solid #475569;
  border-radius: 5px;
  background: rgba(15, 23, 42, 0.26);
}

.lrk-answer small { color: #64748b; font-size: 8px; }
.lrk-answer strong { color: #f8fafc; font-size: 15px; }
.lrk-answer em { color: #94a3b8; font-size: 8px; font-style: normal; }
.lrk-answer span.target { border-color: #c084fc; }
.lrk-answer span.changed { border-color: #10b981; background: rgba(16, 185, 129, 0.15); box-shadow: inset 0 0 0 1px rgba(16, 185, 129, 0.24); }
.lrk-answer span.finalized { border-color: rgba(16, 185, 129, 0.56); }

[data-theme="light"] .loud-rich-kahn { color: #1e293b; }
[data-theme="light"] .lrk-phases > span { border-color: #cbd5e1; color: #94a3b8; }
[data-theme="light"] .lrk-phases > span.active { border-color: #d97706; background: #fffbeb; color: #92400e; }
[data-theme="light"] .lrk-phases > span.done { border-color: #059669; color: #047857; }
