[data-theme="light"] .lrk-relations strong,
[data-theme="light"] .lrk-queue-flow section strong,
[data-theme="light"] .lrk-rule code,
[data-theme="light"] .lrk-edge-action strong,
[data-theme="light"] .lrk-degree-action strong,
[data-theme="light"] .lrk-seed-action strong,
