[data-theme="light"] .lrk-relations > div > span.active { background: #fffbeb; border-color: #d97706; }
[data-theme="light"] .lrk-queue-flow section > span { background: #f8fafc; border-color: #cbd5e1; }
[data-theme="light"] .lrk-node circle { fill: #e2e8f0; }
[data-theme="light"] .lrk-node.ready circle { fill: #e0f2fe; }
[data-theme="light"] .lrk-node.queued circle,
[data-theme="light"] .lrk-node.target circle { fill: #f3e8ff; }
[data-theme="light"] .lrk-node.processed circle { fill: #d1fae5; }
[data-theme="light"] .lrk-node.seed circle,
[data-theme="light"] .lrk-node.source circle { fill: #fef3c7; }
[data-theme="light"] .lrk-node text.person { fill: #0f172a; }
[data-theme="light"] .lrk-node text.quiet,
[data-theme="light"] .lrk-node text.best,
[data-theme="light"] .lrk-node text.degree { fill: #475569; }
