[data-theme="light"] .lrk-rule,
[data-theme="light"] .lrk-edge-action { background: #f0f9ff; }
[data-theme="light"] .lrk-degree-action,
[data-theme="light"] .lrk-seed-action.ready { background: #ecfdf5; }
[data-theme="light"] .lrk-seed-action.locked { background: #fef2f2; }
[data-theme="light"] .lrk-rule span,
[data-theme="light"] .lrk-edge-action span,
[data-theme="light"] .lrk-degree-action span,
[data-theme="light"] .lrk-seed-action span,
[data-theme="light"] .lrk-compare span b { color: #475569; }
[data-theme="light"] .lrk-compare > span.candidate { background: #f0f9ff; border-color: #38bdf8; }
[data-theme="light"] .lrk-indegree span.ready { background: #f0f9ff; border-color: #38bdf8; }
[data-theme="light"] .lrk-indegree span.queued { background: #faf5ff; border-color: #a78bfa; }

@media (max-width: 900px) {
  .lrk-main { grid-template-columns: minmax(0, 1fr); }
  .lrk-svg { max-height: 390px; }
}

@media (max-width: 680px) {
  .lrk-phases { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .lrk-direction { grid-template-columns: auto auto auto; }
  .lrk-direction span { grid-column: 1 / -1; text-align: left; }
  .lrk-relations header,
  .lrk-indegree header,
  .lrk-answer header { align-items: flex-start; flex-direction: column; }
  .lrk-relations header span,
  .lrk-indegree header span,
  .lrk-answer header span { text-align: left; }
  .lrk-queue-flow { grid-template-columns: minmax(0, 1fr); }
  .lrk-queue-flow > b { justify-self: center; transform: rotate(90deg); }
  .lrk-compare { grid-template-columns: minmax(0, 1fr); }
  .lrk-compare > div { min-height: 48px; }
  .lrk-topo { align-items: flex-start; flex-direction: column; }
}

.loud-rich-viz {
  display: grid;
  gap: 11px;
  min-width: 0;
  color: #e2e8f0;
  text-align: left;
}

.loud-rich-phases {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 5px;
}

.loud-rich-phases span {
  padding: 6px 5px;
  border-bottom: 2px solid #334155;
  color: #64748b;
  font-size: 12px;
  font-weight: 750;
  text-align: center;
  white-space: nowrap;
}

.loud-rich-phases span.active {
  border-color: #f59e0b;
  color: #fbbf24;
}

.loud-rich-phases span.done {
  border-color: #10b981;
  color: #6ee7b7;
}

.loud-rich-relations {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border: 1px solid #334155;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.68);
}

.loud-rich-relations > div:first-child {
  display: grid;
  min-width: 105px;
}

.loud-rich-relations > div:first-child strong {
  color: #f8fafc;
  font-size: 12px;
  letter-spacing: 0.04em;
}

.loud-rich-relations > div:first-child small {
  color: #94a3b8;
  font-size: 11px;
}

.loud-rich-relations > div:last-child {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.loud-rich-relations > div:last-child > span {
  display: inline-grid;
  min-width: 82px;
  padding: 4px 7px;
  border: 1px solid #475569;
  border-radius: 6px;
  color: #cbd5e1;
  text-align: center;
}

.loud-rich-relations span small,
.loud-rich-relations span em {
  color: #94a3b8;
  font-size: 10px;
  font-style: normal;
  font-weight: 700;
}

.loud-rich-relations span b {
  color: #f8fafc;
  font-size: 14px;
}

.loud-rich-relations span.built {
  border-color: #10b981;
  background: rgba(16, 185, 129, 0.1);
}

.loud-rich-relations span.built em {
  color: #6ee7b7;
}

.loud-rich-relations span.current {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.14);
  box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.2);
}

.loud-rich-relations span.current small,
.loud-rich-relations span.current em {
  color: #fbbf24;
}

.loud-rich-main {
  display: grid;
  grid-template-columns: minmax(320px, 1.2fr) minmax(220px, 0.8fr);
  gap: 12px;
  align-items: stretch;
}

.loud-rich-graph,
.loud-rich-debug {
  min-width: 0;
}

.loud-rich-graph {
  display: grid;
  align-content: center;
  gap: 5px;
}

.loud-rich-svg {
  display: block;
  width: 100%;
  max-height: 390px;
  overflow: visible;
}

.loud-rich-svg marker path {
  fill: #94a3b8;
}

.loud-rich-svg marker#loud-rich-arrow-active path {
  fill: #f59e0b;
}

.loud-rich-edge {
  stroke-linecap: round;
  transition: stroke 0.2s ease, opacity 0.2s ease;
}

.loud-rich-edge.unbuilt {
  stroke: #64748b;
  stroke-width: 1.8;
  stroke-dasharray: 5 5;
  opacity: 0.44;
}

.loud-rich-edge.built {
  stroke: #94a3b8;
  stroke-width: 2.8;
  opacity: 0.94;
}

.loud-rich-edge.active {
  stroke: #f59e0b;
  stroke-width: 4.5;
  opacity: 1;
}

.loud-rich-node circle {
  fill: #1e293b;
  stroke: #64748b;
  stroke-width: 1.5;
}

.loud-rich-node.done circle {
  fill: #123b36;
  stroke: #10b981;
}

.loud-rich-node.in-stack circle {
  stroke: #38bdf8;
  stroke-width: 3;
}

.loud-rich-node.neighbor circle {
  fill: #3b0764;
  stroke: #a78bfa;
  stroke-width: 3;
}

.loud-rich-node.candidate circle {
  fill: #064e3b;
  stroke: #4ade80;
  stroke-width: 3.5;
}

.loud-rich-node.current circle {
  fill: #422006;
  stroke: #f59e0b;
  stroke-width: 3.5;
}

.loud-rich-node text {
  fill: #e2e8f0;
  text-anchor: middle;
  pointer-events: none;
}

.loud-rich-node text.quiet {
  fill: #94a3b8;
  font-size: 14px;
  font-weight: 700;
}

.loud-rich-node text.person {
  fill: #f8fafc;
  font-size: 22px;
  font-weight: 850;
}

.loud-rich-node text.memo {
  fill: #cbd5e1;
  font-size: 12px;
  font-weight: 700;
}

.loud-rich-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 7px 12px;
  color: #94a3b8;
  font-size: 11px;
}

.loud-rich-legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.loud-rich-legend i {
  width: 10px;
  height: 10px;
  border: 2px solid #64748b;
  border-radius: 50%;
}

.loud-rich-legend i.current { border-color: #f59e0b; background: #422006; }
.loud-rich-legend i.neighbor { border-color: #a78bfa; background: #3b0764; }
.loud-rich-legend i.done { border-color: #10b981; background: #123b36; }

.loud-rich-debug {
  display: grid;
  align-content: start;
  gap: 9px;
}

.loud-rich-stack {
  display: grid;
  gap: 5px;
}

.loud-rich-stack > strong,
.loud-rich-memo-table > strong {
  color: #94a3b8;
  font-size: 11px;
  letter-spacing: 0.04em;
}

.loud-rich-stack > div {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  min-height: 39px;
}

.loud-rich-stack span {
  display: inline-grid;
  padding: 4px 7px;
  border: 1px solid #475569;
  border-radius: 6px;
  text-align: center;
}

.loud-rich-stack span.top {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.12);
}

.loud-rich-stack span small {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
}

.loud-rich-stack span b {
  color: #f8fafc;
  font-size: 13px;
}

.loud-rich-stack i,
.loud-rich-stack em {
  color: #64748b;
  font-size: 12px;
  font-style: normal;
}

.loud-rich-frame,
.loud-rich-memo-hit,
.loud-rich-rule {
  display: grid;
  gap: 4px;
  padding: 10px;
  border-left: 3px solid #38bdf8;
  background: rgba(56, 189, 248, 0.08);
}

.loud-rich-frame small,
.loud-rich-memo-hit small {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
}

.loud-rich-frame strong,
.loud-rich-memo-hit strong {
  color: #f8fafc;
  font-size: 16px;
}

.loud-rich-frame span,
.loud-rich-memo-hit span,
.loud-rich-rule span {
  color: #cbd5e1;
  font-size: 12px;
}

.loud-rich-memo-hit {
  border-left-color: #10b981;
  background: rgba(16, 185, 129, 0.09);
}

.loud-rich-memo-hit small,
.loud-rich-memo-hit strong {
  color: #6ee7b7;
}

.loud-rich-rule code {
  color: #7dd3fc;
  font-size: 13px;
  font-weight: 750;
}

.loud-rich-compare {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 7px;
}

.loud-rich-compare > span {
  display: grid;
  padding: 8px;
  border: 1px solid #475569;
  border-radius: 7px;
  text-align: center;
}

.loud-rich-compare > span.candidate {
  border-color: #8b5cf6;
  background: rgba(139, 92, 246, 0.1);
}

.loud-rich-compare span small {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
