.loud-rich-memo-table span small {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 700;
}

.loud-rich-memo-table span b {
  color: #cbd5e1;
  font-size: 12px;
}

.loud-rich-memo-table span em {
  min-height: 14px;
  color: #94a3b8;
  font-size: 10px;
  font-style: normal;
