[data-theme="light"] .kruskal-cell.component-3 rect { fill: #fef3c7; }
[data-theme="light"] .kruskal-cell.component-4 rect { fill: #fce7f3; }
[data-theme="light"] .kruskal-cell.component-5 rect { fill: #e2e8f0; }
[data-theme="light"] .kruskal-cell text.height { fill: #0f172a; }
