.effort-dijkstra-guide {
  display: grid;
  gap: 10px;
  width: min(100%, 760px);
  margin: 0 auto 14px;
  color: #e2e8f0;
  text-align: left;
}

.effort-phases {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.effort-phases span {
  padding: 6px 8px;
  border-bottom: 2px solid #334155;
  color: #64748b;
  font-size: 11px;
  font-weight: 750;
  text-align: center;
}

.effort-phases span.active {
  border-color: #f59e0b;
  color: #fbbf24;
}

.effort-phases span.done {
  border-color: #10b981;
  color: #6ee7b7;
}

.effort-guide-main {
  display: grid;
  gap: 9px;
}

.effort-heap-lane {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  padding: 9px 10px;
  border: 1px solid #334155;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.68);
}

.effort-heap-lane > div:first-child {
  display: grid;
  min-width: 98px;
}

.effort-heap-lane > div:first-child strong {
  color: #f8fafc;
  font-size: 11px;
  letter-spacing: 0.04em;
}

.effort-heap-lane > div:first-child small,
.effort-heap-more {
  color: #94a3b8;
  font-size: 10px;
}

.effort-heap-lane > div:last-child {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.effort-heap-lane > div:last-child > span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 31px;
  padding: 4px 7px;
  border: 1px solid #475569;
  border-radius: 6px;
  color: #cbd5e1;
  font-size: 11px;
}

.effort-heap-lane > div:last-child > span small {
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
}

.effort-heap-lane > div:last-child > span strong {
  color: #f8fafc;
  font-size: 14px;
}

.effort-heap-lane > div:last-child > span.top {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.13);
  color: #fde68a;
}

.effort-heap-lane > div:last-child > span.top small,
.effort-heap-lane > div:last-child > span.top strong {
  color: #fbbf24;
}

.effort-route-row,
.effort-formula-row {
