  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 7px;
}

.effort-route-row > span {
  display: grid;
  min-width: 125px;
  padding: 6px 10px;
  border: 1px solid #475569;
  border-radius: 7px;
  text-align: center;
}

.effort-route-row > span.current-cell {
  border-color: #f59e0b;
  background: rgba(245, 158, 11, 0.12);
}

.effort-route-row > span.neighbor-cell {
  border-color: #8b5cf6;
  background: rgba(139, 92, 246, 0.13);
}

.effort-route-row small,
.effort-formula-row small {
  color: #94a3b8;
  font-size: 10px;
  font-style: normal;
  font-weight: 750;
}

.effort-route-row strong {
  color: #f8fafc;
  font-size: 14px;
}

.effort-route-row em {
  color: #cbd5e1;
  font-size: 10px;
  font-style: normal;
}

.effort-key-idea {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 38px;
  color: #94a3b8;
  font-size: 11px;
}

.effort-key-idea code {
  color: #a7f3d0;
  font-size: 12px;
  font-weight: 750;
}

.effort-formula-row > span:not(.effort-decision) {
  display: grid;
  min-width: 105px;
  padding: 6px 10px;
  border-bottom: 2px solid #475569;
  text-align: center;
}

.effort-formula-row > span strong {
  color: #f8fafc;
  font-size: 18px;
}

.effort-formula-row > span.new-effort {
  border-color: #38bdf8;
}

.effort-decision {
  display: grid;
  min-width: 92px;
  padding: 5px 9px;
  border: 1px solid #475569;
  border-radius: 7px;
  color: #cbd5e1;
  font-size: 11px;
  font-weight: 800;
  text-align: center;
}

.effort-decision.update {
  border-color: #10b981;
  background: rgba(16, 185, 129, 0.13);
  color: #6ee7b7;
