/* ---- Prevent mobile scroll jumping during step navigation ---- */

/* ---- LeetCode 3518: k-th palindromic rearrangement ---- */
.kth-palindrome-viz {
  min-height: 330px;
  padding: 18px;
  display: grid;
  gap: 14px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.28);
}

.kp-row,
.kp-chars,
.kp-counts,
.kp-result,
.kp-rank-strip,
.kp-candidate-head,
.kp-candidate-title {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.kp-label {
  min-width: 74px;
  color: #94a3b8;
  font: 700 11px/1 "SFMono-Regular", Consolas, monospace;
  text-transform: uppercase;
}

.kp-char,
.kp-result-cell {
  width: 38px;
  min-height: 46px;
  padding: 5px;
  display: grid;
  place-items: center;
  gap: 3px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 6px;
  background: rgba(30, 41, 59, 0.68);
}

.kp-char span,
.kp-result-cell span {
  color: #94a3b8;
  font: 700 8px/1 "SFMono-Regular", Consolas, monospace;
}

.kp-char strong,
.kp-result-cell strong {
  color: #f8fafc;
  font-size: 17px;
  line-height: 1;
}

.kp-ellipsis {
  min-width: 24px;
  color: #94a3b8;
  font: 700 13px/1 "SFMono-Regular", Consolas, monospace;
  text-align: center;
}

.kp-rank-strip {
  padding-left: 81px;
}

.kp-rank-strip > span {
  min-width: 112px;
  padding: 7px 9px;
  display: inline-flex;
  justify-content: space-between;
  gap: 10px;
  border-left: 3px solid #64748b;
  background: rgba(30, 41, 59, 0.52);
  color: #94a3b8;
  font: 700 10px/1.2 "SFMono-Regular", Consolas, monospace;
  text-transform: uppercase;
}

.kp-rank-strip > span:nth-child(1) { border-left-color: #fbbf24; }
.kp-rank-strip > span:nth-child(2) { border-left-color: #22d3ee; }
.kp-rank-strip > span:nth-child(3) { border-left-color: #a78bfa; }
.kp-rank-strip strong { color: #f8fafc; text-transform: none; }

.kp-count {
  min-width: 88px;
  min-height: 52px;
  padding: 6px 9px;
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 3px 8px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  border-radius: 6px;
  background: rgba(30, 41, 59, 0.54);
}

.kp-count strong { grid-row: 1 / 3; color: #f8fafc; font-size: 21px; }
.kp-count span { color: #cbd5e1; font-size: 10px; }
.kp-count small { color: #6ee7b7; font-size: 10px; }
.kp-count.active { border-color: #fbbf24; background: rgba(245, 158, 11, 0.13); }
.kp-count.empty:not(.active) { opacity: 0.45; }

.kp-candidate-section {
  display: grid;
  gap: 8px;
}

.kp-candidate-title {
  padding-left: 81px;
  justify-content: space-between;
  color: #94a3b8;
  font: 700 10px/1 "SFMono-Regular", Consolas, monospace;
  text-transform: uppercase;
}

.kp-candidate-title b { color: #67e8f9; }

.kp-candidates {
  padding-left: 81px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(118px, 1fr));
  gap: 7px;
}

.kp-candidate {
  min-height: 82px;
  padding: 8px;
  display: grid;
  gap: 6px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  border-radius: 6px;
  background: rgba(30, 41, 59, 0.52);
}

.kp-candidate-head { justify-content: space-between; }
.kp-candidate-head strong { color: #f8fafc; font-size: 21px; }
.kp-candidate-head span { color: #94a3b8; font: 700 8px/1 "SFMono-Regular", Consolas, monospace; }
.kp-candidate > div:not(.kp-candidate-head) { display: flex; justify-content: space-between; gap: 6px; }
.kp-candidate small { color: #94a3b8; font: 700 9px/1 "SFMono-Regular", Consolas, monospace; text-transform: uppercase; }
.kp-candidate b { color: #e2e8f0; font: 700 10px/1 "SFMono-Regular", Consolas, monospace; }
.kp-candidate.trying,
.kp-candidate.counted { border-color: #f59e0b; background: rgba(245, 158, 11, 0.12); }
.kp-candidate.skipped { opacity: 0.42; border-style: dashed; }
.kp-candidate.chosen { border-color: #10b981; background: rgba(16, 185, 129, 0.14); }
.kp-candidate.contains-target:not(.chosen):not(.skipped) { box-shadow: inset 0 -3px 0 #22d3ee; }

.kp-formula {
  min-height: 34px;
  padding: 9px 12px;
  border-left: 3px solid #818cf8;
  background: rgba(99, 102, 241, 0.08);
  color: #c7d2fe;
  font: 700 12px/1.3 "SFMono-Regular", Consolas, monospace;
  text-align: center;
  overflow-wrap: anywhere;
}

.kp-half-guide {
  padding-left: 81px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 10px;
  color: #94a3b8;
  font: 700 9px/1 "SFMono-Regular", Consolas, monospace;
  text-align: center;
}

.kp-half-guide span:first-child { color: #6ee7b7; }
.kp-half-guide span:last-child { color: #c4b5fd; }
.kp-result-cell.left { border-color: rgba(52, 211, 153, 0.46); }
.kp-result-cell.right { border-color: rgba(167, 139, 250, 0.46); }
.kp-result-cell.center { border-color: rgba(251, 191, 36, 0.7); background: rgba(245, 158, 11, 0.1); }
.kp-result-cell.filled { background: rgba(34, 211, 238, 0.08); }
.kp-result-cell.active { border-color: #22d3ee; box-shadow: 0 0 0 2px rgba(34, 211, 238, 0.12); }
.kp-result-cell.final { border-color: #10b981; background: rgba(16, 185, 129, 0.14); }

[data-theme="light"] .kth-palindrome-viz { border-color: #cbd5e1; background: #ffffff; }
[data-theme="light"] .kp-label,
[data-theme="light"] .kp-char span,
[data-theme="light"] .kp-result-cell span,
[data-theme="light"] .kp-ellipsis,
[data-theme="light"] .kp-candidate-title,
[data-theme="light"] .kp-candidate small,
[data-theme="light"] .kp-candidate-head span { color: #64748b; }
[data-theme="light"] .kp-char,
[data-theme="light"] .kp-result-cell,
[data-theme="light"] .kp-count,
[data-theme="light"] .kp-candidate { border-color: #cbd5e1; background: #f8fafc; }
[data-theme="light"] .kp-char strong,
[data-theme="light"] .kp-result-cell strong,
[data-theme="light"] .kp-count strong,
[data-theme="light"] .kp-rank-strip strong,
[data-theme="light"] .kp-candidate-head strong,
[data-theme="light"] .kp-candidate b { color: #0f172a; }
[data-theme="light"] .kp-rank-strip > span { background: #f8fafc; color: #64748b; }
[data-theme="light"] .kp-count span { color: #334155; }
[data-theme="light"] .kp-count small { color: #047857; }
[data-theme="light"] .kp-count.active,
[data-theme="light"] .kp-candidate.trying,
[data-theme="light"] .kp-candidate.counted { border-color: #d97706; background: #fffbeb; }
[data-theme="light"] .kp-candidate.chosen { border-color: #059669; background: #ecfdf5; }
[data-theme="light"] .kp-formula { color: #3730a3; background: #eef2ff; }
[data-theme="light"] .kp-result-cell.left { border-color: #10b981; }
[data-theme="light"] .kp-result-cell.right { border-color: #8b5cf6; }
[data-theme="light"] .kp-result-cell.center { border-color: #d97706; background: #fffbeb; }
[data-theme="light"] .kp-result-cell.filled { background: #ecfeff; }
[data-theme="light"] .kp-result-cell.final { border-color: #059669; background: #ecfdf5; }

@media (max-width: 640px) {
  .kth-palindrome-viz { padding: 14px 10px; }
  .kp-label { min-width: 100%; }
  .kp-rank-strip,
  .kp-candidate-title,
  .kp-candidates,
  .kp-half-guide { padding-left: 0; }
  .kp-rank-strip > span { flex: 1 1 120px; }
  .kp-candidates { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .kp-half-guide { grid-template-columns: 1fr; }
}

/* ---- LeetCode 3517: smallest palindromic rearrangement ---- */
.smallest-palindrome-viz {
  min-height: 270px;
  padding: 18px;
  display: grid;
  gap: 14px;
  align-content: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.28);
}

.sp-row,
.sp-source,
.sp-counts,
.sp-result,
.sp-state {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.sp-label {
  min-width: 58px;
  color: #94a3b8;
  font: 700 11px/1 "SFMono-Regular", Consolas, monospace;
  text-transform: uppercase;
}

.sp-source-cell,
.sp-result-cell {
  width: 44px;
  min-height: 50px;
  padding: 5px 7px;
  display: grid;
  place-items: center;
  gap: 3px;
  position: relative;
  border: 1px solid rgba(148, 163, 184, 0.3);
  border-radius: 6px;
  background: rgba(30, 41, 59, 0.72);
}

.sp-source-cell span,
.sp-result-cell span {
  color: #94a3b8;
  font: 700 9px/1 "SFMono-Regular", Consolas, monospace;
}

.sp-source-cell strong,
.sp-result-cell strong {
  color: #f8fafc;
  font-size: 18px;
  line-height: 1;
}

.sp-source-cell.active {
  border-color: #22d3ee;
  background: rgba(34, 211, 238, 0.15);
}

.sp-source-cell.first-half { border-bottom-color: #34d399; }
.sp-source-cell.source-center { border-bottom-color: #fbbf24; }
.sp-source-pointer {
  position: absolute;
  top: -17px;
  left: 50%;
  transform: translateX(-50%);
  padding: 2px 6px;
  border-radius: 5px;
  color: #083344;
  background: #67e8f9;
  font: 800 10px/1 "SFMono-Regular", Consolas, monospace;
